NAME = 'VulgSistine: Vulgata Sistina'
BOOK = 'II Chronicles'

CHAPTERS = {
    1: {
        1: 'Confortatus est ergo Salomon filius David in regno suo, et Dominus erat cum eo, et magnificavit eum in excelsum.',
        2: 'Praecepitque Salomon universo Israeli, tribunis, et centurionibus, et ducibus, et iudicibus omnis Israel, et principibus familiarum:',
        3: 'et abiit cum universa multitudine in Excelsum Gabaon, ubi erat tabernaculum foederis Domini, quod fecit Moyses famulus Dei in solitudine.',
        4: 'Arcam autem Dei adduxerat David de Cariathiarim in locum, quem praeparaverat ei, et ubi fixerat illi tabernaculum, hoc est, in Ierusalem.',
        5: 'Altare quoque aeneum, quod fabricatus fuerat Beseleel filius Uri filii Hur, ibi erat coram tabernaculo Domini: quod et requisivit Salomon, et omnis ecclesia.',
        6: 'Ascenditque Salomon ad altare aeneum, coram tabernaculo foederis Domini, et obtulit in eo mille hostias.',
        7: 'Ecce autem in ipsa nocte apparuit ei Deus, dicens: Postula quod vis, ut dem tibi.',
        8: 'Dixitque Salomon Deo: Tu fecisti cum David patre meo misericordiam magnam: et constituisti me regem pro eo.',
        9: 'Nunc ergo Domine Deus impleatur sermo tuus, quem pollicitus es David patri meo: tu enim me fecisti regem super populum tuum multum, qui tam innumerabilis est, quam pulvis terrae.',
        10: 'Da mihi sapientiam et intelligentiam, ut ingrediar et egrediar coram populo tuo: quis enim potest hunc populum tuum digne, qui tam grandis est, iudicare?',
        11: 'Dixit autem Deus ad Salomonem: Quia hoc magis placuit cordi tuo, et non postulasti divitias, et substantiam, et gloriam, neque animas eorum qui te oderant, sed nec dies vitae plurimos: petisti autem sapientiam et scientiam, ut iudicare possis populum meum, super quem constitui te regem.',
        12: 'Sapientia et scientia data sunt tibi: divitias autem et substantiam et gloriam dabo tibi, ita ut nullus in regibus nec ante te nec post te fuerit similis tui.',
        13: 'Venit ergo Salomon ab Excelso Gabaon in Ierusalem coram tabernaculo foederis, et regnavit super Israel.',
        14: 'Congregavitque sibi currus et equites, et facti sunt ei mille quadringenti currus, et duodecim millia equitum: et fecit eos esse in urbibus quadrigarum, et cum rege in Ierusalem.',
        15: 'Praebuitque rex argentum et aurum in Ierusalem quasi lapides, et cedros quasi sycomoros, quae nascuntur in campestribus multitudine magna.',
        16: 'Adducebantur autem ei equi de Aegypto, et de Coa a negotiatoribus regis, qui ibant, et emebant pretio,',
        17: 'quadrigam equorum sexcentis argenteis, et equum centum quinquaginta: similiter de universis regnis Cethaeorum, et a regibus Syriae emptio celebrabatur.',
    },
    2: {
        1: 'Decrevit autem Salomon aedificare domum nomini Domini, et palatium sibi.',
        2: 'Et numeravit septuaginta millia virorum portantium humeris, et octoginta millia qui caederent lapides in montibus, praepositosque eorum tria millia sexcentos.',
        3: 'Misit quoque ad Hiram regem Tyri, dicens: Sicut egisti cum David patre meo, et misisti ei ligna cedrina ut aedificaret sibi domum, in qua et habitavit:',
        4: 'sic fac mecum ut aedificem domum nomini Domini Dei mei, ut consecrem eam ad adolendum incensum coram illo, et fumiganda aromata, et ad propositionem panum sempiternam, et ad holocautomata mane, et vespere, sabbatis quoque, et neomeniis, et sollemnitatibus Domini Dei nostri in sempiternum, quae mandata sunt Israeli.',
        5: 'Domus enim, quam aedificare cupio, magna est: magnus est enim Deus noster super omnes deos.',
        6: 'Quis ergo poterit praevalere, ut aedificet ei dignam domum? si caelum, et caeli caelorum capere eum nequeunt: quantus ego sum, ut possim aedificare ei domum? sed ad hoc tantum, ut adoleatur incensum coram illo.',
        7: 'Mitte ergo mihi virum eruditum, qui noverit operari in auro, et argento, aere, et ferro, purpura, coccino, et hyacintho, et qui sciat sculpere caelaturas cum his artificibus, quos mecum habeo in Iudaea, et Ierusalem, quos praeparavit David pater meus.',
        8: 'Sed et ligna cedrina mitte mihi, et arceuthina, et pinea de Libano: scio enim quod servi tui noverint caedere ligna de Libano, et erunt servi mei cum servis tuis,',
        9: 'ut parentur mihi ligna plurima. Domus enim, quam cupio aedificare, magna est nimis, et inclyta.',
        10: 'Praeterea operariis, qui caesuri sunt ligna, servis tuis dabo in cibaria tritici coros viginti millia, et hordei coros totidem, olei quoque sata viginti millia.',
        11: 'Dixit autem Hiram rex Tyri per litteras, quas miserat Salomoni: Quia dilexit Dominus populum suum, idcirco te regnare fecit super eum.',
        12: 'Et addidit, dicens: Benedictus Dominus Deus Israel, qui fecit caelum et terram, qui dedit David regi filium sapientem et eruditum et sensatum atque prudentem, ut aedificaret domum Domino, et palatium sibi.',
        13: 'Misi ergo tibi virum prudentem et scientissimum Hiram, ut patrem meum,',
        14: 'filium mulieris de filiabus Dan, cuius pater fuit Tyrius, qui novit operari in auro, et argento, aere, et ferro, et marmore, et lignis, in purpura quoque, et hyacintho, et bysso, et coccino: et qui scit caelare omnem sculpturam, et adinvenire prudenter quodcumque in opere necessarium est cum artificibus tuis, et cum artificibus domini mei David patris tui.',
        15: 'Triticum ergo, et hordeum, et oleum, et vinum, quae pollicitus es domine mi, mitte servis tuis.',
        16: 'Nos autem caedemus ligna de Libano, quot necessaria habueris, et applicabimus ea ratibus per mare in Ioppe: tuum autem erit transferre ea in Ierusalem.',
        17: 'Numeravit igitur Salomon omnes viros proselytos, qui erant in terra Israel, post dinumerationem, quam dinumeravit David pater eius, et inventi sunt centum quinquaginta tria millia et sexcenti.',
        18: 'Fecitque ex eis septuaginta millia, qui humeris onera portarent, et octoginta millia, qui lapides de montibus caederent: tria autem millia et sexcentos praepositos operum populi.',
    },
    3: {
        1: 'Et coepit Salomon aedificare domum Domini in Ierusalem in monte Moria, qui demonstratus fuerat David patri eius, in loco, quem paraverat David in area Ornan Iebusaei.',
        2: 'Coepit autem aedificare mense secundo, anno quarto regni sui.',
        3: 'Et haec sunt fundamenta, quae iecit Salomon, ut aedificaret domum Dei, longitudinis cubitos in mensura prima sexaginta, latitudinis cubitos viginti.',
        4: 'Porticum vero ante frontem, quae tendebatur in longum iuxta mensuram latitudinis domus, cubitorum viginti: porro altitudo centum viginti cubitorum erat: et deauravit eam intrinsecus auro mundissimo.',
        5: 'Domum quoque maiorem texit tabulis ligneis abiegnis, et laminas auri obrizi affixit per totum: sculpsitque in ea palmas, et quasi catenulas se invicem complectentes.',
        6: 'Stravit quoque pavimentum templi pretiosissimo marmore, decore multo.',
        7: 'Porro aurum erat probatissimum, de cuius laminis texit domum, et trabes eius, et postes, et parietes, et ostia: et caelavit cherubim in parietibus.',
        8: 'Fecit quoque domum Sancti sanctorum: longitudinem iuxta latitudinem domus cubitorum viginti: et latitudinem similiter viginti cubitorum: et laminis aureis texit eam, quasi talentis sexcentis.',
        9: 'Sed et clavos fecit aureos, ita ut singuli clavi siclos quinquagenos appenderent: caenacula quoque texit auro.',
        10: 'Fecit etiam in domo Sancti sanctorum cherubim duos, opere statuario: et texit eos auro.',
        11: 'Alae cherubim viginti cubitis extendebantur, ita ut una ala haberet cubitos quinque et tangeret parietem domus: et altera quinque cubitos habens, alam tangeret alterius cherub.',
        12: 'Similiter cherub alterius ala, quinque habebat cubitos, et tangebat parietem: et ala eius altera quinque cubitorum, alam cherub alterius contingebat.',
        13: 'Igitur alae utriusque cherubim expansae erant, et extendebantur per cubitos viginti: ipsi autem stabant erectis pedibus, et facies eorum erant versae ad exteriorem domum.',
        14: 'Fecit quoque velum ex hyacintho, purpura, cocco, et bysso: et intexuit ei cherubim.',
        15: 'Ante fores etiam templi duas columnas, quae triginta et quinque cubitos habebant altitudinis: porro capita earum, quinque cubitorum.',
        16: 'Necnon et quasi catenulas in oraculo, et superposuit eas capitibus columnarum: malogranata etiam centum, quae catenulis interposuit.',
        17: 'Ipsas quoque columnas posuit in vestibulo templi, unam a dextris, et alteram a sinistris: eam, quae a dextris erat, vocavit Iachin: et quae ad laevam, Booz.',
    },
    4: {
        1: 'Fecit quoque altare aeneum viginti cubitorum longitudinis, et viginti cubitorum latitudinis, et decem cubitorum altitudinis.',
        2: 'Mare etiam fusile decem cubitis a labio usque ad labium, rotundum per circuitum: quinque cubitos habebat altitudinis, et funiculus triginta cubitorum ambiebat gyrum eius.',
        3: 'Similitudo quoque boum erat subter illud, et decem cubitis quaedam extrinsecus caelaturae, quasi duobus versibus alvum maris circuibant. Boves autem erant fusiles:',
        4: 'et ipsum Mare super duodecim boves impositum erat, quorum tres respiciebant ad Aquilonem, et alii tres ad Occidentem: porro tres alii Meridiem, et tres qui reliqui erant, Orientem, habentes mare superpositum: posteriora autem boum erant intrinsecus sub mari.',
        5: 'Porro vastitas eius habebat mensuram palmi, et labium illius erat quasi labium calicis, vel repandi lilii: capiebatque tria millia metretas.',
        6: 'Fecit quoque conchas decem: et posuit quinque a dextris, et quinque a sinistris, ut lavarent in eis omnia, quae in holocaustum oblaturi erant: porro in mari sacerdotes lavabantur.',
        7: 'Fecit autem et candelabra aurea decem secundum speciem, qua iusserat fieri: et posuit ea in templo, quinque a dextris, et quinque a sinistris.',
        8: 'Necnon et mensas decem: et posuit eas in templo, quinque a dextris, et quinque a sinistris: phialas quoque aureas centum.',
        9: 'Fecit etiam atrium sacerdotum, et basilicam grandem: et ostia in basilica, quae texit aere.',
        10: 'Porro mare posuit in latere dextro contra Orientem ad Meridiem.',
        11: 'Fecit autem Hiram lebetes, et creagras, et phialas: et complevit omne opus regis in domo Dei:',
        12: 'hoc est, columnas duas, et epistylia, et capita, et quasi quaedam retiacula, quae capita tegerent super epistylia.',
        13: 'Malogranata quoque quadringenta, et retiacula duo ita ut bini ordines malogranatorum singulis retiaculis iungerentur, quae protegerent epistylia, et capita columnarum.',
        14: 'Bases etiam fecit, et conchas, quas superposuit basibus:',
        15: 'mare unum, boves quoque duodecim sub mari.',
        16: 'Et lebetes, et creagras, et phialas. Omnia vasa fecit Salomoni Hiram in domo Domini ex aere mundissimo.',
        17: 'In regione Iordanis fudit ea rex in argillosa terra inter Sochot, et Saredatha.',
        18: 'Erat autem multitudo vasorum innumerabilis, ita ut ignoraretur pondus aeris.',
        19: 'Fecitque Salomon omnia vasa domus Dei, et altare aureum, et mensas, et super eas panes propositionis:',
        20: 'candelabra quoque cum lucernis suis ut lucerent ante oraculum iuxta ritum ex auro purissimo:',
        21: 'et florentia quaedam, et lucernas, et forcipes aureos: omnia de auro mundissimo facta sunt.',
        22: 'Thymiateria quoque, et thuribula, et phialas, et mortariola ex auro purissimo. Et ostia caelavit templi interioris, id est, in Sancto sanctorum: et ostia templi forinsecus aurea. Sicque completum est omne opus, quod fecit Salomon in domo Domini.',
    },
    5: {
        1: 'Intulit igitur Salomon omnia, quae voverat David pater suus, argentum, et aurum, et universa vasa posuit in thesauris domus Dei.',
        2: 'Post quae congregavit maiores natu Israel, et cunctos principes tribuum, et capita familiarum de filiis Israel in Ierusalem, ut adducerent arcam foederis Domini de Civitate David, quae est Sion.',
        3: 'Venerunt itaque ad regem omnes viri Israel in die sollemni mensis septimi.',
        4: 'Cumque venissent cuncti seniorum Israel, portaverunt Levitae arcam,',
        5: 'et intulerunt eam, et omnem paraturam tabernaculi. Porro vasa sanctuarii, quae erant in tabernaculo, portaverunt Sacerdotes cum Levitis.',
        6: 'Rex autem Salomon, et universus coetus Israel, et omnes, qui fuerunt congregati ante arcam, immolabant arietes, et boves absque ullo numero: tanta enim erat multitudo victimarum.',
        7: 'Et intulerunt Sacerdotes arcam foederis Domini in locum suum, id est, ad oraculum templi, in Sancta sanctorum subter alas cherubim:',
        8: 'ita ut cherubim expanderent alas suas super locum, in quo posita erat arca, et ipsam arcam tegerent cum vectibus suis.',
        9: 'Vectium autem, quibus portabatur arca, quia paululum longiores erant, capita parebant ante oraculum: si vero quis paululum fuisset extrinsecus, eos videre non poterat. Fuit itaque arca ibi usque in praesentem diem.',
        10: 'Nihilque erat aliud in arca, nisi duae tabulae, quas posuerat Moyses in Horeb, quando legem dedit Dominus filiis Israel egredientibus ex Aegypto.',
        11: 'Egressis autem Sacerdotibus de sanctuario (omnes enim Sacerdotes, qui ibi potuerant inveniri, sanctificati sunt: nec adhuc in illo tempore vices, et ministeriorum ordo inter eos divisus erat)',
        12: 'tam Levitae quam cantores, id est, et qui sub Asaph erant, et qui sub Eman, et qui sub Idithun, filii, et fratres eorum vestiti byssinis, cymbalis, et psalteriis, et citharis concrepabant, stantes ad Orientalem plagam altaris, et cum eis Sacerdotes centum viginti canentes tubis.',
        13: 'Igitur cunctis pariter, et tubis, et voce, et cymbalis, et organis, et diversi generis musicorum concinentibus, et vocem in sublime tollentibus; longe sonitus audiebatur, ita ut cum Dominum laudare coepissent et dicere: Confitemini Domino quoniam bonus, quoniam in aeternum misericordia eius; impleretur ita domus Dei nube,',
        14: 'ne possent Sacerdotes stare et ministrare propter caliginem. Compleverat enim gloria Domini domum Dei.',
    },
    6: {
        1: 'Tunc Salomon ait: Dominus pollicitus est ut habitaret in caligine:',
        2: 'ego autem aedificavi domum nomini eius, ut habitaret ibi in perpetuum.',
        3: 'Et convertit rex faciem suam, et benedixit universae multitudini Israel (nam omnis turba stabat intenta) et ait:',
        4: 'Benedictus Dominus Deus Israel, qui quod locutus est David patri meo, opere complevit, dicens:',
        5: 'A die, qua eduxi populum meum de Terra Aegypti, non elegi civitatem de cunctis tribubus Israel, ut aedificaretur in ea domus nomini meo: neque elegi quemquam alium virum, ut esset dux in populo Israel,',
        6: 'sed elegi Ierusalem, ut sit nomen meum in ea, et elegi David, ut constituerem eum super populum meum Israel.',
        7: 'Cumque fuisset voluntatis David patris mei, ut aedificaret domum nomini Domini Dei Israel,',
        8: 'dixit Dominus ad eum: Quia haec fuit voluntas tua, ut aedificares domum nomini meo, bene quidem fecisti huiuscemodi habere voluntatem:',
        9: 'sed non tu aedificabis domum, verum filius tuus, qui egredietur de lumbis tuis, ipse aedificabit domum nomini meo.',
        10: 'Complevit ergo Dominus sermonem suum, quem locutus fuerat: et ego surrexi pro David patre meo, et sedi super thronum Israel, sicut locutus est Dominus: et aedificavi domum nomini Domini Dei Israel.',
        11: 'Et posui in ea arcam, in qua est pactum Domini, quod pepigit cum filiis Israel.',
        12: 'Stetit ergo coram altari Domini ex adverso universae multitudinis Israel, et extendit manus suas.',
        13: 'Siquidem fecerat Salomon basim aeneam, et posuerat eam in medio basilicae, habentem quinque cubitos longitudinis, et quinque cubitos latitudinis, et tres cubitos altitudinis: stetitque super eam: et deinceps flexis genibus contra universam multitudinem Israel, et palmis in caelum levatis,',
        14: 'ait: Domine Deus Israel, non est similis tui Deus in caelo et in terra: qui custodis pactum et misericordiam cum servis tuis, qui ambulant coram te in toto corde suo:',
        15: 'Qui praestitisti servo tuo David patri meo quaecumque locutus fueras ei: et quae ore promiseras, opere complesti, sicut et praesens tempus probat.',
        16: 'Nunc ergo Domine Deus Israel, imple servo tuo patri meo David quaecumque locutus es, dicens: Non deficiet ex te vir coram me, qui sedeat super thronum Israel: ita tamen si custodierint filii tui vias meas, et ambulaverint in lege mea, sicut et tu ambulasti coram me.',
        17: 'Et nunc Domine Deus Israel, firmetur sermo tuus, quem locutus es servo tuo David.',
        18: 'Ergone credibile est ut habitet Deus cum hominibus super terram? Si caelum et caeli caelorum non te capiunt, quanto magis domus ista, quam aedificavi?',
        19: 'Sed ad hoc tantum facta est, ut respicias orationem servi tui, et obsecrationem eius, Domine Deus meus: et audias preces, quas fundit famulus tuus coram te:',
        20: 'ut aperias oculos tuos super domum istam diebus ac noctibus, super locum, in quo pollicitus es ut invocaretur nomen tuum,',
        21: 'et exaudires orationem, quam servus tuus orat in eo: et exaudias preces famuli tui, et populi tui Israel. Quicumque oraverit in loco isto, exaudi de habitaculo tuo, id est, de caelis, et propitiare.',
        22: 'Si peccaverit quispiam in proximum suum, et iurare contra eum paratus venerit, seque maledicto constrinxerit coram altari in domo ista:',
        23: 'tu audies de caelo, et facies iudicium servorum tuorum, ita ut reddas iniquo viam suam in caput proprium, et ulciscaris iustum, retribuens ei secundum iustitiam suam.',
        24: 'Si superatus fuerit populus tuus Israel ab inimicis (peccabunt enim tibi) et conversi egerint poenitentiam, et obsecraverint nomen tuum, et fuerint deprecati in loco isto,',
        25: 'tu exaudies de caelo, et propitiare peccato populi tui Israel, et reduc eos in terram, quam dedisti eis, et patribus eorum.',
        26: 'Si clauso caelo pluvia non fluxerit propter peccata populi, et deprecati te fuerint in loco isto, et confessi nomini tuo, et conversi a peccatis suis, cum eos afflixeris,',
        27: 'exaudi de caelo Domine, et dimitte peccata servis tuis et populi tui Israel, et doce eos viam bonam, per quam ingrediantur: et da pluviam terrae, quam dedisti populo tuo ad possidendum.',
        28: 'Fames si orta fuerit in terra et pestilentia, aerugo, et aurugo, et locusta, et bruchus, et hostes, vastatis regionibus, portas obsederint civitatis, omnisque plaga et infirmitas presserit:',
        29: 'si quis de populo tuo Israel fuerit deprecatus, cognoscens plagam et infirmitatem suam, et expanderit manus suas in domo hac,',
        30: 'tu exaudies de caelo, de sublimi scilicet habitaculo tuo, et propitiare, et redde unicuique secundum vias suas, quas nosti eum habere in corde suo: (tu enim solus nosti corda filiorum hominum.)',
        31: 'ut timeant te, et ambulent in viis tuis cunctis diebus, quibus vivunt super faciem terrae, quam dedisti patribus nostris.',
        32: 'Externum quoque, qui non est de populo tuo Israel, si venerit de terra longinqua, propter nomen tuum magnum, et propter manum tuam robustam, et brachium tuum extentum, et adoraverit in loco isto,',
        33: 'tu exaudies de caelo firmissimo habitaculo tuo, et facies cuncta, pro quibus invocaverit te ille peregrinus: ut sciant omnes populi terrae nomen tuum, et timeant te sicut populus tuus Israel. et cognoscant, quia nomen tuum invocatum est super domum hanc, quam aedificavi.',
        34: 'Si egressus fuerit populus tuus ad bellum contra adversarios suos per viam in qua miseris eos, adorabunt te contra viam, in qua civitas haec est, quam elegisti, et domus, quam aedificavi nomini tuo:',
        35: 'tu exaudies de caelo preces eorum, et obsecrationem, et ulciscaris.',
        36: 'Si autem peccaverint tibi (neque enim est homo, qui non peccet) et iratus fueris eis, et tradideris hostibus, et captivos duxerint eos in terram longinquam, vel certe quae iuxta est,',
        37: 'et conversi in corde suo in terra, ad quam captivi ducti fuerant, egerint poenitentiam, et deprecati te fuerint in terra captivitatis suae, dicentes: Peccavimus, inique fecimus, iniuste egimus:',
        38: 'et reversi fuerint ad te in toto corde suo, et in tota anima sua, in terra captivitatis suae, ad quam ducti sunt, adorabunt te contra viam terrae suae, quam dedisti patribus eorum, et urbis, quam elegisti, et domus, quam aedificavi nomini tuo:',
        39: 'tu exaudies de caelo, hoc est, de firmo habitaculo tuo preces eorum, et facias iudicium, et dimittas populo tuo, quamvis peccatori:',
        40: 'tu es enim Deus meus: aperiantur, quaeso, oculi tui, et aures tuae intentae sint ad orationem, quae fit in loco isto.',
        41: 'Nunc igitur consurge Domine Deus in requiem tuam, tu et arca fortitudinis tuae: Sacerdotes tui Domine Deus induantur salutem, et sancti tui laetentur in bonis.',
        42: 'Domine Deus ne avertaris faciem christi tui: memento misericordiarum David servi tui.',
    },
    7: {
        1: 'Cumque complesset Salomon fundens preces, ignis descendit de caelo, et devoravit holocausta et victimas: et maiestas Domini implevit domum.',
        2: 'Nec poterant sacerdotes ingredi templum Domini, eo quod implesset maiestas Domini templum Domini.',
        3: 'Sed et omnes filii Israel videbant descendentem ignem, et gloriam Domini super domum: et corruentes proni in terram super pavimentum stratum lapide, adoraverunt, et laudaverunt Dominum: Quoniam bonus, quoniam in saeculum misericordia eius.',
        4: 'Rex autem, et omnis populus immolabant victimas coram Domino.',
        5: 'Mactavit igitur rex Salomon hostias, boum vigintiduo millia, arietum centum viginti millia: et dedicavit domum Dei rex, et universus populus.',
        6: 'Sacerdotes autem stabant in officiis suis: et Levitae in organis carminum Domini, quae fecit David rex ad laudandum Dominum: Quoniam in aeternum misericordia eius, hymnos David canentes per manus suas: porro Sacerdotes canebant tubis ante eos, cunctusque Israel stabat.',
        7: 'Sanctificavit quoque Salomon medium atrii ante templum Domini: obtulerat enim ibi holocausta et adipes pacificorum: quia altare aeneum, quod fecerat, non poterat sustinere holocausta et sacrificia et adipes.',
        8: 'Fecit ergo Salomon sollemnitatem in tempore illo septem diebus, et omnis Israel cum eo, ecclesia magna valde, ab introitu Emath usque ad Torrentem Aegypti.',
        9: 'Fecitque die octavo collectam, eo quod dedicasset altare septem diebus, et sollemnitatem celebrasset diebus septem.',
        10: 'Igitur in die vigesimo tertio mensis septimi dimisit populos ad tabernacula sua, laetantes atque gaudentes super bono, quod fecerat Dominus Davidi, et Salomoni, et Israeli populo suo.',
        11: 'Complevitque Salomon domum Domini, et domum regis, et omnia quae disposuerat in corde suo, ut faceret in domo Domini, et in domo sua, et prosperatus est.',
        12: 'Apparuit autem ei Dominus nocte, et ait: Audivi orationem tuam, et elegi locum istum mihi in domum sacrificii.',
        13: 'Si clausero caelum, et pluvia non fluxerit, et mandavero et praecepero locustae, ut devoret terram, et misero pestilentiam in populum meum:',
        14: 'conversus autem populus meus, super quos invocatum est nomen meum, deprecatus me fuerit, et exquisierit faciem meam, et egerit poenitentiam a viis suis pessimis: et ego exaudiam de caelo, et propitius ero peccatis eorum, et sanabo terram eorum.',
        15: 'Oculi quoque mei erunt aperti, et aures meae erectae ad orationem eius, qui in loco isto oraverit.',
        16: 'Elegi enim, et sanctificavi locum istum, ut sit nomen meum ibi in sempiternum, et permaneant oculi mei, et cor meum ibi cunctis diebus.',
        17: 'Tu quoque si ambulaveris coram me, sicut ambulaverit David pater tuus, et feceris iuxta omnia, quae praecepi tibi, et iustitias meas iudiciaque servaveris:',
        18: 'suscitabo thronum regni tui, sicut pollicitus sum David patri tuo, dicens: Non auferetur de stirpe tua vir, qui non sit princeps in Israel.',
        19: 'Si autem aversi fueritis, et dereliqueritis iustitias meas, et praecepta mea, quae proposui vobis, et abeuntes servieritis diis alienis, et adoraveritis eos,',
        20: 'evellam vos de terra mea, quam dedi vobis: et domum hanc, quam sanctificavi nomini meo, proiiciam a facie mea, et tradam eam in parabolam, et in exemplum cunctis populis.',
        21: 'Et domus ista erit in proverbium universis transeuntibus, et dicent stupentes: Quare fecit Dominus sic terrae huic, et domui huic?',
        22: 'Respondebuntque: Quia dereliquerunt Dominum Deum patrum suorum, qui eduxit eos de Terra Aegypti, et apprehenderunt deos alienos, et adoraverunt eos, et coluerunt: idcirco venerunt super eos universa haec mala.',
    },
    8: {
        1: 'Expletis autem viginti annis postquam aedificavit Salomon domum Domini et domum suam:',
        2: 'civitates, quas dederat Hiram Salomoni, aedificavit, et habitare ibi fecit filios Israel.',
        3: 'Abiit quoque in Emath Suba, et obtinuit eam.',
        4: 'Et aedificavit Palmiram in deserto, et alias civitates munitissimas aedificavit in Emath.',
        5: 'Extruxitque Bethoron superiorem, et Bethoron inferiorem, civitates muratas habentes portas et vectes et seras:',
        6: 'Balaath etiam et omnes urbes firmissimas, quae fuerunt Salomonis, cunctasque urbes quadrigarum, et urbes equitum. omnia quaecumque voluit Salomon atque disposuit, aedificavit in Ierusalem et in Libano, et in universa terra potestatis suae.',
        7: 'Omnem populum, qui derelictus fuerat de Hethaeis, et Amorrhaeis, et Pherezaeis, et Hevaeis, et Iebusaeis, qui non erant de stirpe Israel,',
        8: 'de filiis eorum: et de posteris, quos non interfecerant filii Israel, subiugavit Salomon in tributarios, usque in diem hanc.',
        9: 'Porro de filiis Israel non posuit ut servirent operibus regis: ipsi enim erant viri bellatores, et duces primi, et principes quadrigarum et equitum eius.',
        10: 'Omnes autem principes exercitus regis Salomonis fuerunt ducenti quinquaginta, qui erudiebant populum.',
        11: 'Filiam vero Pharaonis transtulit de Civitate David in domum, quam aedificaverat ei. Dixit enim rex: Non habitabit uxor mea in domo David regis Israel, eo quod sanctificata sit: quia ingressa est in eam arca Domini.',
        12: 'Tunc obtulit Salomon holocausta Domino super altare Domini, quod extruxerat ante porticum,',
        13: 'ut per singulos dies offerretur in eo iuxta praeceptum Moysi in sabbatis et in calendis, et in festis diebus, ter per annum, id est, in sollemnitate azymorum, et in sollemnitatem hebdomadarum, et in sollemnitate tabernaculorum.',
        14: 'Et constituit iuxta dispositionem David patris sui officia Sacerdotum in ministeriis suis: et Levitas in ordine suo, ut laudarent, et ministrarent coram Sacerdotibus iuxta ritum uniuscuiusque diei: et ianitores in divisionibus suis per portam et portam: sic enim praeceperat David homo Dei.',
        15: 'Nec praetergressi sunt de mandatis regis tam Sacerdotes, quam Levitae ex omnibus, quae praeceperat, etiam in custodiis thesaurorum.',
        16: 'Omnes impensas praeparatas habuit Salomon ex eo die, quo fundavit domum Domini usque in diem, quo perfecit eam.',
        17: 'Tunc abiit Salomon in Asiongaber, et in Ailath ad oram Maris rubri, quae est in Terra Edom.',
        18: 'Misit autem ei Hiram per manus servorum suorum naves, et nautas gnaros maris, et abierunt cum servis Salomonis in Ophir, tuleruntque inde quadringenta quinquaginta talenta auri, et attulerunt ad regem Salomonem.',
    },
    9: {
        1: 'Regina quoque Saba, cum audisset famam Salomonis, venit ut tentaret eum in aenigmatibus in Ierusalem, cum magnis opibus et camelis, qui portabant aromata, et auri plurimum, gemmasque pretiosas. Cumque venisset ad Salomonem, locuta est ei quaecumque erant in corde suo.',
        2: 'Et exposuit ei Salomon omnia quae proposuerat: nec quidquam fuit, quod non perspicuum ei fecerit.',
        3: 'Quae postquam vidit, sapientiam scilicet Salomonis, et domum quam aedificaverat,',
        4: 'necnon et cibaria mensae eius, et habitacula servorum, et officia ministrorum eius, et vestimenta eorum, pincernas quoque et vestes eorum, et victimas quas immolabat in domo Domini: non erat prae stupore ultra in ea spiritus.',
        5: 'Dixitque ad regem: Verus est sermo, quem audieram in terra mea de virtutibus et sapientia tua.',
        6: 'Non credebam narrantibus donec ipsa venissem, et vidissent oculi mei, et probassem vix medietatem sapientiae tuae mihi fuisse narratam: vicisti famam virtutibus tuis.',
        7: 'Beati viri tui, et beati servi tui, qui assistunt coram te omni tempore, et audiunt sapientiam tuam.',
        8: 'Sit Dominus Deus tuus benedictus, qui voluit te ordinare super thronum suum, regem Domini Dei tui. Quia diligit Deus Israel, et vult servare eum in aeternum, idcirco posuit te super eum regem ut facias iudicia atque iustitiam.',
        9: 'Dedit autem regi centum viginti talenta auri, et aromata multa nimis, et gemmas pretiosissimas: non fuerunt aromata talia ut haec, quae dedit regina Saba regi Salomoni.',
        10: 'Sed et servi Hiram cum servis Salomonis attulerunt aurum de Ophir, et ligna thyina, et gemmas pretiosissimas:',
        11: 'de quibus fecit rex, de lignis scilicet thyinis, gradus in domo Domini, et in domo regia, citharas quoque, et psalteria cantoribus: numquam visa sunt in Terra Iuda ligna talia.',
        12: 'Rex autem Salomon dedit reginae Saba cuncta quae voluit, et quae postulavit, et multo plura quam attulerat ad eum: quae reversa, abiit in terram suam cum servis suis.',
        13: 'Erat autem pondus auri, quod afferebatur Salomoni per singulos annos, sexcenta sexaginta sex talenta auri:',
        14: 'excepta ea summa, quam legati diversarum gentium, et negotiatores afferre consueverant, omnesque reges Arabiae, et satrapae terrarum, qui comportabant aurum, et argentum Salomoni.',
        15: 'Fecit igitur rex Salomon ducentas hastas aureas de summa sexcentorum aureorum, qui in singulis hastis expendebantur:',
        16: 'trecenta quoque scuta aurea trecentorum aureorum, quibus tegebantur singula scuta: posuitque ea rex in armentario, quod erat consitum nemore.',
        17: 'Fecit quoque rex solium eburneum grande, et vestivit illud auro mundissimo.',
        18: 'Sex quoque gradus, quibus ascendebatur ad solium, et scabellum aureum, et brachiola duo altrinsecus, et duos leones stantes iuxta brachiola,',
        19: 'sed et alios duodecim leunculos stantes super sex gradus ex utraque parte: non fuit tale solium in universis regnis.',
        20: 'Omnia quoque vasa convivii regis erant aurea, et vasa domus saltus Libani ex auro purissimo. Argentum enim in diebus illis pro nihilo reputabatur.',
        21: 'Siquidem naves regis ibant in Tharsis cum servis Hiram, semel in annis tribus: et deferebant inde aurum et argentum, et ebur, et simias, et pavos.',
        22: 'Magnificatus est igitur Salomon super omnes reges terrae prae divitiis et gloria.',
        23: 'Omnesque reges terrarum desiderabant videre faciem Salomonis, ut audirent sapientiam, quam dederat Deus in corde eius:',
        24: 'et deferebant ei munera, vasa argentea, et aurea, et vestes, et arma, et aromata, equos, et mulos, per singulos annos.',
        25: 'Habuit quoque Salomon quadraginta millia equorum in stabulis, et curruum, equitumque duodecim millia, constituitque eos in urbibus quadrigarum, et ubi erat rex in Ierusalem.',
        26: 'Exercuit etiam potestatem super cunctos reges a flumine Euphrate usque ad terram Philisthinorum, et usque ad terminos Aegypti.',
        27: 'Tantamque copiam praebuit argenti in Ierusalem quasi lapidum: et cedrorum tantam multitudinem velut sycomororum, quae gignuntur in campestribus.',
        28: 'Adducebantur autem ei equi de Aegypto, cunctisque regionibus.',
        29: 'Reliqua autem operum Salomonis priorum et novissimorum scripta sunt in verbis Nathan Prophetae, et in libris Ahiae Silonitis, in visione quoque Addo Videntis, contra Ieroboam filium Nabat.',
        30: 'Regnavit autem Salomon in Ierusalem super omnem Israel quadraginta annis.',
        31: 'Dormivitque cum patribus suis, et sepelierunt eum in Civitate David: regnavitque Roboam filius eius pro eo.',
    },
    10: {
        1: 'Profectus est autem Roboam in Sichem: illuc enim cunctus Israel convenerat ut constituerent eum regem.',
        2: 'Quod cum audisset Ieroboam filius Nabat, qui erat in Aegypto (fugerat quippe illuc ante Salomonem) statim reversus est.',
        3: 'Vocaveruntque eum, et venit cum universo Israel, et locuti sunt ad Roboam, dicentes:',
        4: 'Pater tuus durissimo iugo nos pressit, tu leviora impera patre tuo, qui nobis imposuit gravem servitutem, et paululum de onere subleva, ut serviamus tibi.',
        5: 'Qui ait: Post tres dies revertimini ad me. Cumque abiisset populus,',
        6: 'iniit consilium cum senibus, qui steterant coram patre eius Salomone dum adhuc viveret, dicens: Quid datis consilii ut respondeam populo?',
        7: 'Qui dixerunt ei: Si placueris populo huic, et leniveris eos verbis clementibus, servient tibi omni tempore.',
        8: 'At ille reliquit consilium senum, et cum iuvenibus tractare coepit, qui cum eo nutriti fuerant, et erant in comitatu illius.',
        9: 'Dixitque ad eos: Quid vobis videtur? vel respondere quid debeo populo huic, qui dixit mihi: Subleva iugum quod imposuit nobis pater tuus?',
        10: 'At illi responderunt ut iuvenes, et nutriti cum eo in deliciis, atque dixerunt: Sic loqueris populo, qui dixit tibi: Pater tuus aggravavit iugum nostrum, tu subleva: et sic respondebis ei: Minimus digitus meus grossior est lumbis patris mei.',
        11: 'Pater meus imposuit vobis grave iugum, et ego maius pondus apponam: pater meus cecidit vos flagellis, ego vero caedam vos scorpionibus.',
        12: 'Venit ergo Ieroboam, et universus populus ad Roboam die tertio, sicut praeceperat eis.',
        13: 'Responditque rex dura, derelicto consilio seniorum:',
        14: 'locutusque est iuxta iuvenum voluntatem: Pater meus grave vobis imposuit iugum, quod ego gravius faciam: pater meus cecidit vos flagellis, ego vero caedam vos scorpionibus.',
        15: 'Et non acquievit populi precibus: erat enim voluntatis Dei ut compleretur sermo eius, quem locutus fuerat per manum Ahiae Silonitis ad Ieroboam filium Nabat.',
        16: 'Populus autem universus rege duriora dicente, sic locutus est ad eum: Non est nobis pars in David, neque hereditas in filio Isai. Revertere in tabernacula tua Israel, tu autem pasce domum tuam David. Et abiit Israel in tabernacula sua.',
        17: 'Super filios autem Israel, qui habitabant in civitatibus Iuda, regnavit Roboam.',
        18: 'Misitque rex Roboam Aduram, qui praeerat tributis, et lapidaverunt eum filii Israel, et mortuus est: porro rex Roboam currum festinavit ascendere, et fugit in Ierusalem.',
        19: 'Recessitque Israel a domo David, usque ad diem hanc.',
    },
    11: {
        1: 'Venit autem Roboam in Ierusalem, et convocavit universam domum Iuda et Beniamin, centum octoginta millia electorum atque bellantium, ut dimicaret contra Israel, et converteret ad se regnum suum.',
        2: 'Factusque est sermo Domini ad Semeiam hominem Dei, dicens:',
        3: 'Loquere ad Roboam filium Salomonis regem Iuda, et ad universum Israel, qui est in Iuda et Beniamin:',
        4: 'Haec dicit Dominus: Non ascendetis, neque pugnabitis contra fratres vestros: revertatur unusquisque in domum suam, quia mea hoc gestum est voluntate. Qui cum audissent sermonem Domini reversi sunt, nec perrexerunt contra Ieroboam.',
        5: 'Habitavit autem Roboam in Ierusalem, et aedificavit civitates muratas in Iuda.',
        6: 'Extruxitque Bethlehem, et Etam, et Thecue,',
        7: 'Bethsur quoque, et Socho, et Odollam,',
        8: 'necnon et Geth, et Maresa, et Ziph,',
        9: 'sed et Aduram, et Lachis, et Azeca,',
        10: 'Saraa quoque, et Aialon, et Hebron, quae erant in Iuda et Beniamin, civitates munitissimas.',
        11: 'Cumque clausisset eas muris, posuit in eis principes, ciborumque horrea, hoc est, olei, et vini.',
        12: 'Sed et in singulis urbibus fecit armamentarium scutorum et hastarum, firmavitque eas summa diligentia, et imperavit super Iudam, et Beniamin.',
        13: 'Sacerdotes autem et Levitae, qui erant in universo Israel, venerunt ad eum de cunctis sedibus suis,',
        14: 'relinquentes suburbana, et possessiones suas, et transeuntes ad Iudam, et Ierusalem: eo quod abiecisset eos Ieroboam, et posteri eius, ne sacerdotio Domini fungerentur.',
        15: 'Qui constituit sibi sacerdotes excelsorum, et daemoniorum, vitulorumque quos fecerat.',
        16: 'Sed et de cunctis tribubus Israel, quicumque dederant cor suum ut quaererent Dominum Deum Israel, venerunt in Ierusalem ad immolandum victimas suas coram Domino Deo patrum suorum.',
        17: 'Et roboraverunt regnum Iuda, et confirmaverunt Roboam filium Salomonis per tres annos: ambulaverunt enim in viis David et Salomonis, annis tantum tribus.',
        18: 'Duxit autem Roboam uxorem Mahalath, filiam Ierimoth, filii David: Abihail quoque filiam Eliab filii Isai,',
        19: 'quae peperit ei filios Iehus, et Somoriam, et Zoom.',
        20: 'Post hanc quoque accepit Maacha filiam Absalom, quae peperit ei Abia, et Ethai, et Ziza, et Salomith.',
        21: 'Amavit autem Roboam Maacha filiam Absalom super omnes uxores suas, et concubinas: nam uxores decem et octo duxerat, concubinas autem sexaginta: et genuit viginti octo filios, et sexaginta filias.',
        22: 'Constituit vero in capite, Abiam filium Maacha ducem super omnes fratres suos: ipsum enim regem facere cogitabat,',
        23: 'quia sapientior fuit, et potentior super omnes filios eius, et in cunctis finibus Iuda, et Beniamin, et in universis civitatibus muratis: praebuitque eis escas plurimas, et multas petivit uxores.',
    },
    12: {
        1: 'Cumque roboratum fuisset regnum Roboam et confortatum, dereliquit legem Domini, et omnis Israel cum eo.',
        2: 'Anno autem quinto regni Roboam, ascendit Sesac rex Aegypti in Ierusalem (quia peccaverant Domino)',
        3: 'cum mille ducentis curribus, et sexaginta millibus equitum: nec erat numerus vulgi quod venerat cum eo ex Aegypto, Libyes scilicet, et Troglodytae, et Aethiopes.',
        4: 'Cepitque civitates munitissimas in Iuda, et venit usque in Ierusalem.',
        5: 'Semeias autem propheta ingressus est ad Roboam, et principes Iuda, qui congregati fuerant in Ierusalem, fugientes Sesac, dixitque ad eos: Haec dicit Dominus: Vos reliquistis me, et ego reliqui vos in manu Sesac.',
        6: 'Consternatique principes Israel et rex dixerunt: Iustus est Dominus.',
        7: 'Cumque vidisset Dominus, quod humiliati essent, factus est sermo Domini ad Semeiam, dicens: Quia humiliati sunt, non disperdam eos, daboque eis pauxillum auxilii, et non stillabit furor meus super Ierusalem per manum Sesac.',
        8: 'Verumtamen servient ei, ut sciant distantiam servitutis meae, et servitutis regni terrarum.',
        9: 'Recessit itaque Sesac rex Aegypti ab Ierusalem, sublatis thesauris domus Domini, et domus regis, omniaque secum tulit, et clypeos aureos, quos fecerat Salomon,',
        10: 'pro quibus fecit rex aeneos, et tradidit illos principibus scutariorum, qui custodiebant vestibulum palatii.',
        11: 'Cumque introiret rex domum Domini, veniebant scutarii, et tollebant eos, iterumque referebant eos ad armamentarium suum.',
        12: 'Verumtamen quia humiliati sunt, aversa est ab eis ira Domini, nec deleti sunt penitus: siquidem et in Iuda inventa sunt opera bona.',
        13: 'Confortatus est ergo rex Roboam in Ierusalem, atque regnavit: quadraginta autem et unius anni erat cum regnare coepisset, et decem et septem annis regnavit in Ierusalem, urbe, quam elegit Dominus, ut confirmaret nomen suum ibi, de cunctis tribubus Israel: nomen autem matris eius Naama Ammanitis.',
        14: 'Fecit autem malum, et non praeparavit cor suum ut quaereret Dominum.',
        15: 'Opera vero Roboam prima et novissima scripta sunt in Libris Semeiae prophetae, et Addo Videntis, et diligenter exposita: pugnaveruntque adversum se Roboam, et Ieroboam cunctis diebus.',
        16: 'Et dormivit Roboam cum patribus suis, sepultusque est in Civitate David. Et regnavit Abia filius eius pro eo.',
    },
    13: {
        1: 'Anno octavodecimo regis Ieroboam, regnavit Abia super Iudam.',
        2: 'Tribus annis regnavit in Ierusalem, nomenque matris eius Michaia, filia Uriel de Gabaa: et erat bellum inter Abiam et Ieroboam.',
        3: 'Cumque iniisset Abia certamen, et haberet bellicosissimos viros, et electorum quadraginta millia: Ieroboam instruxit econtra aciem octoginta millia virorum, qui et ipsi electi erant, et ad bella fortissimi.',
        4: 'Stetit ergo Abia super montem Semeron, qui erat in Ephraim, et ait: Audi Ieroboam, et omnis Israel.',
        5: 'Num ignoratis quod Dominus Deus Israel dederit regnum David super Israel in sempiternum, ipsi et filiis eius in pactum salis?',
        6: 'Et surrexit Ieroboam filius Nabat, servus Salomonis filii David: et rebellavit contra dominum suum.',
        7: 'Congregatique sunt ad eum viri vanissimi, et filii Belial: et praevaluerunt contra Roboam filium Salomonis: porro Roboam erat rudis, et corde pavido, nec potuit resistere eis.',
        8: 'Nunc ergo vos dicitis quod resistere possitis regno Domini, quod possidet per filios David, habetisque grandem populi multitudinem, atque vitulos aureos, quos fecit vobis Ieroboam in deos.',
        9: 'Et eiecistis Sacerdotes Domini, filios Aaron, atque Levitas: et fecistis vobis Sacerdotes sicut omnes populi terrarum: quicumque venerit, et initiaverit manum suam in tauro de bobus, et in arietibus septem, fit sacerdos eorum, qui non sunt dii.',
        10: 'Noster autem Dominus, Deus est, quem non relinquimus, Sacerdotesque ministrant Domino de filiis Aaron, et Levitae sunt in ordine suo:',
        11: 'Holocausta quoque offerunt Domino per singulos dies mane et vespere, et thymiama iuxta legis praecepta confectum, et proponuntur panes in mensa mundissima, estque apud nos candelabrum aureum, et lucernae eius, ut accendantur semper ad vesperam: nos quippe custodimus praecepta Domini Dei nostri, quem vos reliquistis.',
        12: 'Ergo in exercitu nostro dux Deus est, et Sacerdotes eius, qui clangunt tubis, et resonant contra vos: filii Israel nolite pugnare contra Dominum Deum patrum vestrorum, quia non vobis expedit.',
        13: 'Haec illo loquente, Ieroboam retro moliebatur insidias. Cumque ex adverso hostium staret, ignorantem Iudam suo ambiebat exercitu.',
        14: 'Respiciensque Iudas vidit instare bellum ex adverso et post tergum, et clamavit ad Dominum: ac Sacerdotes tubis canere coeperunt.',
        15: 'Omnesque viri Iuda vociferati sunt: et ecce illis clamantibus, perterruit Deus Ieroboam, et omnem Israel qui stabat ex adverso Abia et Iuda.',
        16: 'Fugeruntque filii Israel Iudam, et tradidit eos Deus in manu eorum.',
        17: 'Percussit ergo eos Abia, et populus eius plaga magna: et corruerunt vulnerati ex Israel quinquaginta millia virorum fortium.',
        18: 'Humiliatique sunt filii Israel in tempore illo, et vehementissime confortati filii Iuda eo quod sperassent in Domino Deo patrum suorum.',
        19: 'Persecutus est autem Abia fugientem Ieroboam, et cepit civitates eius, Bethel et filias eius, et Iesana cum filiabus suis, Ephron quoque et filias eius:',
        20: 'nec valuit ultra resistere Ieroboam in diebus Abia: quem percussit Dominus, et mortuus est.',
        21: 'Igitur Abia, confortato imperio suo, accepit uxores quattuordecim: procreavitque viginti duos filios, et sedecim filias.',
        22: 'Reliqua autem sermonum Abia, viarumque et operum eius, scripta sunt diligentissime in Libro Addo Prophetae.',
    },
    14: {
        1: 'Dormivit autem Abia cum patribus suis, et sepelierunt eum in Civitate David: regnavitque Asa filius eius pro eo, in cuius diebus quievit terra annis decem.',
        2: 'Fecit autem Asa quod bonum et placitum erat in conspectu Dei sui, et subvertit altaria peregrini cultus, et excelsa,',
        3: 'et confregit statuas, lucosque succidit:',
        4: 'et praecepit Iudae ut quaereret Dominum Deum patrum suorum, et faceret legem, et universa mandata:',
        5: 'et abstulit de cunctis urbibus Iuda aras, et fana, et regnavit in pace.',
        6: 'Aedificavit quoque urbes munitas in Iuda, quia quietus erat, et nulla temporibus eius bella surrexerant, pacem Domino largiente.',
        7: 'Dixit autem Iudae: Aedificemus civitates istas, et vallemus muris, et roboremus turribus, et portis, et seris, donec a bellis quieta sunt omnia, eo quod quaesierimus Dominum Deum patrum nostrorum, et dederit nobis pacem per gyrum. Aedificaverunt igitur, et nullum in extruendo impedimentum fuit.',
        8: 'Habuit autem Asa in exercitu suo portantium scuta et hastas de Iuda trecenta millia, de Beniamin vero scutariorum et sagittariorum ducenta octoginta millia, omnes isti viri fortissimi.',
        9: 'Egressus est autem contra eos Zara Aethiops cum exercitu suo, decies centena millia, et curribus trecentis: et venit usque Maresa.',
        10: 'Porro Asa perrexit obviam ei, et instruxit aciem ad bellum in Valle Sephata, quae est iuxta Maresa:',
        11: 'et invocavit Dominum Deum, et ait: Domine non est apud te ulla distantia utrum in paucis auxilieris, an in pluribus: adiuva nos Domine Deus noster: in te enim, et in tuo nomine habentes fiduciam venimus contra hanc multitudinem. Domine, Deus noster tu es, non praevaleat contra te homo.',
        12: 'Exterruit itaque Dominus Aethiopes coram Asa et Iuda: fugeruntque Aethiopes.',
        13: 'Et persecutus est eos Asa, et populus, qui cum eo erat, usque Gerara: et ruerunt Aethiopes usque ad internecionem, quia Domino caedente contriti sunt, et exercitu illius praeliante. Tulerunt ergo spolia multa,',
        14: 'et percusserunt civitates omnes per circuitum Gerarae: grandis quippe cunctos terror invaserat: et diripuerunt urbes, et multam praedam asportaverunt.',
        15: 'Sed et caulas ovium destruentes, tulerunt pecorum infinitam multitudinem, et camelorum: reversique sunt in Ierusalem.',
    },
    15: {
        1: 'Azarias autem filius Obed, facto in se spiritu Dei,',
        2: 'egressus est in occursum Asa, et dixit ei: Audite me Asa, et omnis Iuda et Beniamin: Dominus vobiscum, quia fuistis cum eo. Si quaesieritis eum, invenietis: si autem dereliqueritis eum, derelinquet vos.',
        3: 'Transibant autem multi dies in Israel absque Deo vero, et absque sacerdote doctore, et absque lege.',
        4: 'Cumque reversi fuerint in angustia sua ad Dominum Deum Israel, et quaesierint eum, reperient eum.',
        5: 'In tempore illo non erit pax egredienti et ingredienti, sed terrores undique in cunctis habitatoribus terrarum:',
        6: 'pugnavit enim gens contra gentem, et civitas contra civitatem, quia Dominus conturbabit eos in omni angustia.',
        7: 'Vos ergo confortamini, et non dissolvantur manus vestrae: erit enim merces operi vestro.',
        8: 'Quod cum audisset Asa verba scilicet, et prophetiam Azariae filii Obed prophetae, confortatus est, et abstulit idola de omni terra Iuda, et de Beniamin, et ex urbibus, quas ceperat, montis Ephraim, et dedicavit altare Domini quod erat ante porticum Domini.',
        9: 'Congregavitque universum Iudam et Beniamin, et advenas cum eis de Ephraim, et de Manasse, et de Simeon: plures enim ad eum confugerant ex Israel, videntes quod Dominus Deus illius esset cum eo.',
        10: 'Cumque venissent in Ierusalem mense tertio, anno decimoquinto regni Asa,',
        11: 'immolaverunt Domino in die illa de manubiis, et praeda, quam adduxerant, boves septingentos, et arietes septem millia.',
        12: 'Et intravit ex more ad corroborandum foedus ut quaererent Dominum Deum patrum suorum in toto corde, et in tota anima sua.',
        13: 'Si quis autem, inquit, non quaesierit Dominum Deum Israel, moriatur, a minimo usque ad maximum, a viro usque ad mulierem.',
        14: 'Iuraveruntque Domino voce magna in iubilo, et in clangore tubae, et in sonitu buccinarum',
        15: 'omnes qui erant in Iuda cum execratione: in omni enim corde suo iuraverunt, et in tota voluntate quaesierunt eum, et invenerunt: praestititque eis Dominus requiem per circuitum.',
        16: 'Sed et Maacham matrem Asa regis ex augusto deposuit imperio, eo quod fecisset in luco simulacrum Priapi: quod omne contrivit, et in frustra comminuens combussit in Torrente cedron:',
        17: 'Excelsa autem derelicta sunt in Israel: attamen cor Asa erat perfectum cunctis diebus eius,',
        18: 'Eaque quae voverat pater suus, et ipse, intulit in domum Domini, argentum, et aurum, vasorumque diversam supellectilem.',
        19: 'Bellum vero non fuit usque ad trigesimum quintum annum regni Asa.',
    },
    16: {
        1: 'Anno autem trigesimo sexto regni eius, ascendit Baasa rex Israel in Iudam, et muro circumdabat Rama, ut nullus tute posset egredi et ingredi de regno Asa.',
        2: 'Protulit ergo Asa argentum et aurum de thesauris domus Domini, et de thesauris regis, misitque ad Benadad regem Syriae, qui habitabat in Damasco, dicens:',
        3: 'Foedus inter me et te est, pater quoque meus et pater tuus habuere concordiam: quam ob rem misi tibi argentum et aurum, ut rupto foedere, quod habes cum Baasa rege Israel, facias eum a me recedere.',
        4: 'Quo comperto, Benadad misit principes exercituum suorum ad urbes Israel: qui percusserunt Ahion, et Dan, et Abelmaim, et universas urbes Nephthali muratas.',
        5: 'Quod cum audisset Baasa desiit aedificare Rama, et intermisit opus suum.',
        6: 'Porro Asa rex assumpsit universum Iudam, et tulerunt lapides de Rama, et ligna quae aedificationi praeparaverat Baasa, aedificavitque ex eis Gabaa, et Maspha.',
        7: 'In tempore illo venit Hanani propheta ad Asam regem Iuda, et dixit ei: Quia habuisti fiduciam in rege Syriae, et non in Domino Deo tuo, idcirco evasit Syriae regis exercitus de manu tua.',
        8: 'Nonne Aethiopes, et Libyes multo plures erant quadrigis, et equitibus, et multitudine nimia: quos, cum in Domino credidisses, tradidit in manu tua?',
        9: 'Oculi enim Domini contemplantur universam terram, et praebent fortitudinem his, qui corde perfecto credunt in eum. Stulte igitur egisti, et propter hoc ex praesenti tempore adversum te bella consurgent.',
        10: 'Iratusque Asa adversus Videntem, iussit eum mitti in nervum: valde quippe super hoc fuerat indignatus: et interfecit de populo in tempore illo plurimos.',
        11: 'Opera autem Asa prima et novissima scripta sunt in Libro regum Iuda et Israel.',
        12: 'Aegrotavit etiam Asa anno trigesimo nono regni sui, dolore pedum vehementissimo, et nec in infirmitate sua quaesivit Dominum, sed magis in medicorum arte confisus est.',
        13: 'Dormivitque cum patribus suis: et mortuus est anno quadragesimo primo regni sui.',
        14: 'Et sepelierunt eum in sepulchro suo quod foderat sibi in Civitate David: posueruntque eum super lectum suum plenum aromatibus et unguentibus meretriciis, quae erant pigmentariorum arte confecta, et combusserunt super eum ambitione nimia.',
    },
    17: {
        1: 'Regnavit autem Iosaphat filius eius pro eo, et invaluit contra Israel.',
        2: 'Constituitque militum numeros in cunctis urbibus Iuda, quae erant vallatae muris. Praesidiaque disposuit in terra Iuda, et in civitatibus Ephraim, quas ceperat Asa pater eius.',
        3: 'Et fuit Dominus cum Iosaphat, quia ambulavit in viis David patris sui primis: et non speravit in Baalim,',
        4: 'sed in Deo patris sui, et perrexit in praeceptis illius et non iuxta peccata Israel.',
        5: 'Confirmavitque Dominus regnum in manu eius, et dedit omnis Iuda munera Iosaphat: factaeque sunt ei infinitae divitiae, et multa gloria.',
        6: 'Cumque sumpsisset cor eius audaciam propter vias Domini, etiam excelsa et lucos de Iuda abstulit.',
        7: 'Tertio autem anno regni sui misit de principibus suis Benhail, et Obdiam, et Zachariam, et Nathanael, et Michaeam ut docerent in civitatibus Iuda:',
        8: 'et cum eis Levitas Semeiam, et Nathaniam, et Zabadiam, Asael quoque, et Semiramoth, et Ionathan, Adoniamque et Thobiam, et Thobadoniam Levitas, et cum eis Elisama, et Ioran Sacerdotes,',
        9: 'docebantque populum in Iuda, habentes librum legis Domini, et circuibant cunctas urbes Iuda, atque erudiebant populum.',
        10: 'Itaque factus est pavor Domini super omnia regna terrarum, quae erant per gyrum Iuda, nec audebant bellare contra Iosaphat.',
        11: 'Sed et Philisthaei Iosaphat munera deferebant, et vectigal argenti, Arabes quoque adducebant pecora, arietum septem millia septingenta, et hircorum totidem.',
        12: 'Crevit ergo Iosaphat, et magnificatus est usque in sublime: atque aedificavit in Iuda domos ad instar turrium, urbesque muratas.',
        13: 'Et multa opera paravit in urbibus Iuda: viri quoque bellatores, et robusti erant in Ierusalem,',
        14: 'quorum iste numerus per domos atque familias singulorum: In Iuda princeps exercitus, Ednas dux, et cum eo robustissimi viri trecenta millia.',
        15: 'Post hunc Iohanan princeps, et cum eo ducenta octoginta millia.',
        16: 'Post istum quoque Amasias filius Zechri, consecratus Domino, et cum eo ducenta millia virorum fortium.',
        17: 'Hunc sequebatur robustus ad praelia Eliada, et cum eo tenentium arcum et clypeum ducenta millia.',
        18: 'Post istum etiam Iozabad, et cum eo centum octoginta millia expeditorum militum.',
        19: 'Hi omnes erant ad manum regis, exceptis aliis, quos posuerat in urbibus muratis, in universo Iuda.',
    },
    18: {
        1: 'Fuit ergo Iosaphat dives et inclytus multum, et affinitate coniunctus est Achab.',
        2: 'Descenditque post annos ad eum in Samariam: ad cuius adventum mactavit Achab arietes, et boves plurimos ipsi, et populo qui venerat cum eo: persuasitque illi ut ascenderet in Ramoth Galaad.',
        3: 'Dixitque Achab rex Israel ad Iosaphat regem Iuda: Veni mecum in Ramoth Galaad. Cui ille respondit: Ut ego, et tu: sicut populus tuus, et populus meus: tecumque erimus in bello.',
        4: 'Dixitque Iosaphat ad regem Israel: Consule obsecro impraesentiarum sermonem Domini.',
        5: 'Congregavit igitur rex Israel prophetarum quadringentos viros, et dixit ad eos: In Ramoth Galaad ad bellandum ire debemus an quiescere? At illi, Ascende, inquiunt, et tradet Deus in manu regis.',
        6: 'Dixitque Iosaphat: Numquid non est hic prophetes Domini, ut ab illo etiam requiramus?',
        7: 'Et ait rex Israel ad Iosaphat: Est vir unus, a quo possumus quaerere Domini voluntatem: sed ego odi eum, quia non prophetat mihi bonum, sed malum omni tempore: est autem Michaeas filius Iemla. Dixitque Iosaphat: Ne loquaris rex hoc modo.',
        8: 'Vocavit ergo rex Israel unum de eunuchis, et dixit ei: Voca cito Michaeam filium Iemla.',
        9: 'Porro rex Israel, et Iosaphat rex Iuda uterque sedebant in solio suo, vestiti cultu regio: sedebant autem in area iuxta portam Samariae, omnesque prophetae vaticinabantur coram eis.',
        10: 'Sedechias vero filius Chanaana fecit sibi cornua ferrea, et ait: Haec dicit Dominus: His ventilabis Syriam, donec conteras eam.',
        11: 'Omnesque prophetae similiter prophetabant, atque dicebant: Ascende in Ramoth Galaad, et prosperaberis, et tradet eos Dominus in manu regis.',
        12: 'Nuncius autem, qui ierat ad vocandum Michaeam, ait illi: En verba omnium prophetarum uno ore bona regi annunciant: quaeso ergo te ut et sermo tuus ab eis non dissentiat, loquarisque prospera.',
        13: 'Cui respondit Michaeas: Vivit Dominus, quia quodcumque dixerit mihi Deus meus, hoc loquar.',
        14: 'Venit ergo ad regem. Cui rex ait: Michaea, ire debemus in Ramoth Galaad ad bellandum, an quiescere? Cui ille respondit: Ascendite: cuncta enim prospera evenient, et tradentur hostes in manus vestras.',
        15: 'Dixitque rex: Iterum, atque iterum te adiuro, ut mihi non loquaris, nisi quod verum est in nomine Domini.',
        16: 'At ille ait: Vidi universum Israel dispersum in montibus, sicut oves absque pastore: et dixit Dominus: Non habent isti dominos: revertatur unusquisque in domum suam in pace.',
        17: 'Et ait rex Israel ad Iosaphat: Nonne dixi tibi, quod non prophetaret iste mihi quidquam boni, sed ea, quae mala sunt?',
        18: 'At ille, Idcirco, ait, audite verbum Domini: Vidi Dominum sedentem in solio suo, et omnem exercitum caeli assistentem ei a dextris et a sinistris.',
        19: 'Et dixit Dominus: Quis decipiet Achab regem Israel ut ascendat et corruat in Ramoth Galaad? Cumque diceret unus hoc modo, et alter alio:',
        20: 'processit spiritus, et stetit coram Domino, et ait: Ego decipiam eum. Cui Dominus, In quo, inquit, decipies?',
        21: 'At ille respondit: Egrediar, et ero spiritus mendax in ore omnium prophetarum eius. Dixitque Dominus: Decipies, et praevalebis: egredere, et fac ita.',
        22: 'Nunc igitur, ecce Dominus dedit spiritum mendacii in ore omnium prophetarum tuorum, et Dominus locutus est de te mala.',
        23: 'Accessit autem Sedechias filius Chanaana, et percussit Michaeae maxillam, et ait: Per quam viam transivit Spiritus Domini a me, ut loqueretur tibi?',
        24: 'Dixitque Michaeas: Tu ipse videbis in die illo, quando ingressus fueris cubiculum de cubiculo ut abscondaris.',
        25: 'Praecepit autem rex Israel, dicens: Tollite Michaeam, et ducite eum ad Amon principem civitatis, et ad Ioas filium Amelech.',
        26: 'Et dicetis: Haec dicit rex: Mittite hunc in carcerem, et date ei panis modicum, et aquae pauxillum, donec revertar in pace.',
        27: 'Dixitque Michaeas: Si reversus fueris in pace, non est locutus Dominus in me. Et ait: Audite omnes populi.',
        28: 'Igitur ascenderunt rex Israel et Iosaphat rex Iuda in Ramoth Galaad.',
        29: 'Dixitque rex Israel ad Iosaphat: Mutabo habitum, et sic ad pugnam vadam, tu autem induere vestibus tuis. Mutatoque rex Israel habitu, venit ad bellum.',
        30: 'Rex autem Syriae praeceperat ducibus equitatus sui, dicens: Ne pugnetis contra minimum, aut contra maximum, nisi contra solum regem Israel.',
        31: 'Itaque cum vidissent principes equitatus Iosaphat, dixerunt: Rex Israel est iste. Et circumdederunt eum dimicantes: at ille clamavit ad Dominum, et auxiliatus est ei, atque avertit eos ab illo.',
        32: 'Cum enim vidissent duces equitatus, quod non esset rex Israel, reliquerunt eum.',
        33: 'Accidit autem ut unus e populo sagittam in incertum iaceret, et percuteret regem Israel inter cervicem et scapulas, at ille aurigae suo ait: Converte manum tuam, et educ me de acie, quia vulneratus sum.',
        34: 'Et finita est pugna in die illo: porro rex Israel stabat in curru suo contra Syros usque ad vesperam, et mortuus est occidente sole.',
    },
    19: {
        1: 'Reversus est autem Iosaphat rex Iuda in domum suam pacifice in Ierusalem.',
        2: 'Cui occurrit Iehu filius Henani Videns, et ait ad eum: Impio praebes auxilium, et his qui oderunt Dominum amicitia iungeris, et idcirco iram quidem Domini merebaris:',
        3: 'sed bona opera inventa sunt in te, eo quod abstuleris lucos de terra Iuda, et praeparaveris cor tuum ut requireres Dominum Deum patrum tuorum.',
        4: 'Habitavit ergo Iosaphat in Ierusalem: rursumque egressus est ad populum de Bersabee usque ad montem Ephraim, et revocavit eos ad Dominum Deum patrum suorum.',
        5: 'Constituitque iudices terrae in cunctis civitatibus Iuda munitis per singula loca,',
        6: 'et praecipiens iudicibus, Videte, ait, quid faciatis: non enim hominis exercetis iudicium, sed Domini: et quodcumque iudicaveritis, in vos redundabit.',
        7: 'Sit timor Domini vobiscum, et cum diligentia cuncta facite: non est enim apud Dominum Deum nostrum iniquitas, nec personarum acceptio, nec cupido munerum.',
        8: 'In Ierusalem quoque constituit Iosaphat Levitas, et Sacerdotes, et Principes familiarum ex Israel, ut iudicium et causam Domini iudicarent habitatoribus eius.',
        9: 'Praecepitque eis, dicens: Sic agetis in timore Domini fideliter et corde perfecto.',
        10: 'Omnem causam, quae venerit ad vos fratrum vestrorum, qui habitant in urbibus suis inter cognationem et cognationem, ubicumque quaestio est de lege, de mandato, de ceremoniis, de iustificationibus: ostendite eis, ut non peccent in Dominum, et ne veniat ira super vos et super fratres vestros: sic ergo agentes non peccabitis.',
        11: 'Amarias autem sacerdos et pontifex vester, in his, quae ad Deum pertinent, praesidebit: porro Zabadias filius Ismahel, qui est dux in domo Iuda, super ea opera erit, quae ad regis officium pertinent: habetisque magistros Levitas coram vobis, confortamini, et agite diligenter, et erit Dominus vobiscum in bonis.',
    },
    20: {
        1: 'Post haec congregati sunt filii Moab, et filii Ammon, et cum eis de Ammonitis ad Iosaphat ut pugnarent contra eum.',
        2: 'Veneruntque nuncii, et indicaverunt Iosaphat, dicentes: Venit contra te multitudo magna de his locis, quae trans mare sunt, et de Syria, et ecce consistunt in Asasonthamar, quae est Engaddi.',
        3: 'Iosaphat autem timore perterritus, totum se contulit ad rogandum Dominum, et praedicavit ieiunium universo Iuda.',
        4: 'Congregatusque est Iudas ad deprecandum Dominum: sed et omnes de urbibus suis venerunt ad obsecrandum eum.',
        5: 'Cumque stetisset Iosaphat in medio coetu Iuda, et Ierusalem, in domo Domini ante atrium novum,',
        6: 'ait: Domine Deus patrum nostrorum, tu es Deus in caelo, et dominaris cunctis regnis Gentium, in manu tua est fortitudo et potentia, nec quisquam tibi potest resistere.',
        7: 'Nonne tu Deus noster interfecisti omnes habitatores terrae huius coram populo tuo Israel, et dedisti eam semini Abraham amici tui in sempiternum?',
        8: 'Habitaveruntque in ea, et extruxerunt in illa sanctuarium nomini tuo, dicentes:',
        9: 'Si irruerint super nos mala, gladius iudicii, pestilentia, et fames, stabimus coram domo hac in conspectu tuo, in qua invocatum est nomen tuum: et clamabimus ad te in tribulationibus nostris, et exaudies, salvosque facies.',
        10: 'Nunc igitur ecce filii Ammon, et Moab, et mons Seir, per quos non concessisti Israel ut transirent quando egrediebantur de Aegypto, sed declinaverunt ab eis, et non interfecerunt illos:',
        11: 'econtrario agunt, et nituntur eiicere nos de possessione, quam tradidisti nobis.',
        12: 'Deus noster, ergo non iudicabis eos? In nobis quidem non est tanta fortitudo, ut possimus huic multitudini resistere, quae irruit super nos. Sed cum ignoremus quid agere debeamus, hoc solum habemus residui, ut oculos nostros dirigamus ad te.',
        13: 'Omnis vero Iuda stabat coram Domino cum parvulis, et uxoribus, et liberis suis.',
        14: 'Erat autem Iahaziel filius Zachariae, filii Banaiae, filii Iehiel, filii Mathaniae, Levites de filiis Asaph, super quem factus est Spiritus Domini in medio turbae,',
        15: 'et ait: Attendite omnis Iuda, et qui habitatis Ierusalem, et tu rex Iosaphat: Haec dicit Dominus vobis: Nolite timere, nec paveatis hanc multitudinem: non est enim vestra pugna, sed Dei.',
        16: 'Cras descendetis contra eos: ascensuri enim sunt per clivum nomine Sis, et invenietis illos in summitate torrentis, qui est contra solitudinem Ieruel.',
        17: 'Non eritis vos qui dimicabitis, sed tantummodo confidenter state, et videbitis auxilium Domini super vos, o Iuda, et Ierusalem: nolite timere, nec paveatis: cras egrediemini contra eos, et Dominus erit vobiscum.',
        18: 'Iosaphat ergo, et Iuda, et omnes habitatores Ierusalem ceciderunt proni in terram coram Domino, et adoraverunt eum.',
        19: 'Porro Levitae de filiis Caath, et de filiis Core laudabant Dominum Deum Israel voce magna, in excelsum.',
        20: 'Cumque mane surrexissent, egressi sunt per desertum Thecue: profectisque eis, stans Iosaphat in medio eorum, dixit: Audite me viri Iuda, et omnes habitatores Ierusalem: credite in Domino Deo vestro, et securi eritis: credite prophetis eius, et cuncta evenient prospera.',
        21: 'Deditque consilium populo, et statuit cantores Domini, ut laudarent eum in turmis suis, et antecederent exercitum, ac voce consona dicerent: Confitemini Domino, quoniam in aeternum misericordia eius.',
        22: 'Cumque coepissent laudes canere, vertit Dominus insidias eorum in semetipsos, filiorum scilicet Ammon, et Moab, et montis Seir, qui egressi fuerant ut pugnarent contra Iudam, et percussi sunt.',
        23: 'Namque filii Ammon, et Moab consurrexerunt adversum habitatores montis Seir, ut interficerent et delerent eos: cumque hoc opere perpetrassent, etiam in semetipsos versi, mutuis concidere vulneribus.',
        24: 'Porro Iuda cum venisset ad speculam, quae respicit solitudinem, vidit procul omnem late regionem plenam cadaveribus, nec superesse quemquam, qui necem potuisset evadere.',
        25: 'Venit ergo Iosaphat, et omnis populus cum eo ad detrahenda spolia mortuorum: inveneruntque inter cadavera variam supellectilem, vestes quoque, et vasa pretiosissima, et diripuerunt ita ut omnia portare non possent, nec per tres dies spolia auferre prae praedae magnitudine.',
        26: 'Die autem quarto congregati sunt in Valle benedictionis: etenim quoniam ibi benedixerant Domino, vocaverunt locum illum Vallis benedictionis usque in praesentem diem.',
        27: 'Reversusque est omnis vir Iuda, et habitatores Ierusalem, et Iosaphat ante eos in Ierusalem cum laetitia magna, eo quod dedisset eis Dominus gaudium de inimicis suis.',
        28: 'Ingressique sunt in Ierusalem cum psalteriis, et citharis, et tubis in domum Domini.',
        29: 'Irruit autem pavor Domini super universa regna terrarum cum audissent quod pugnasset Dominus contra inimicos Israel.',
        30: 'Quievitque regnum Iosaphat, et praebuit ei Deus pacem per circuitum.',
        31: 'Regnavit igitur Iosaphat super Iudam, et erat triginta quinque annorum cum regnare coepisset: viginti autem et quinque annis regnavit in Ierusalem, et nomen matris eius Azuba filia Selahi.',
        32: 'Et ambulavit in via patris suis Asa, nec declinavit ab ea, faciens quae placita erant coram Domino.',
        33: 'Verumtamen excelsa non abstulit, et adhuc populus non direxerat cor suum ad Dominum Deum patrum suorum.',
        34: 'Reliqua autem gestorum Iosaphat priorum et novissimorum scripta sunt in verbis Iehu filii Hanani, quae digessit in Libros regum Israel.',
        35: 'Post haec iniit amicitias Iosaphat rex Iuda cum Ochozia rege Israel, cuius opera fuerunt impiissima.',
        36: 'Et particeps fuit ut faceret naves, quae irent in Tharsis: feceruntque classem in Asiongaber.',
        37: 'Prophetavit autem Eliezer filius Dodau de Maresa ad Iosaphat, dicens: Quia habuisti foedus cum Ochozia, percussit Dominus opera tua, contritaeque sunt naves, nec potuerunt ire in Tharsis.',
    },
    21: {
        1: 'Dormivit autem Iosaphat cum patribus suis, et sepultus est cum eis in Civitate David: regnavitque Ioram filius eius pro eo.',
        2: 'Qui habuit fratres filios Iosaphat, Azariam, et Iahiel, et Zachariam, et Azariam, et Michael, et Saphatiam. omnes hi, filii Iosaphat regis Iuda.',
        3: 'Deditque eis pater suus multa munera argenti, et auri, et pensitationes, cum civitatibus munitissimis in Iuda: regnum autem tradidit Ioram, eo quod esset primogenitus.',
        4: 'Surrexit ergo Ioram super regnum patris sui: cumque se confirmasset, occidit omnes fratres suos gladio, et quosdam de principibus Israel.',
        5: 'Trigintaduorum annorum erat Ioram cum regnare coepisset: et octo annis regnavit in Ierusalem.',
        6: 'Ambulavitque in viis regum Israel, sicut egerat domus Achab: filia quippe Achab erat uxor eius, et fecit malum in conspectu Domini.',
        7: 'Noluit autem Dominus disperdere domum David propter pactum, quod inierat cum eo: et quia promiserat ut daret ei lucernam, et filiis eius omni tempore.',
        8: 'In diebus illis rebellavit Edom, ne esset subditus Iudae, et constituit sibi regem.',
        9: 'Cumque transisset Ioram cum principibus suis, et cuncto equitatu, qui erat secum, surrexit nocte, et percussit Edom qui se circumdederat, et omnes duces equitatus eius.',
        10: 'Attamen rebellavit Edom, ne esset sub ditione Iuda usque ad hanc diem: eo tempore et Lobna recessit ne esset sub manu illius. Dereliquerat enim Dominum Deum patrum suorum:',
        11: 'insuper et excelsa fabricatus est in urbibus Iuda, et fornicari fecit habitatores Ierusalem, et praevaricari Iudam.',
        12: 'Allatae sunt autem ei litterae ab Elia propheta, in quibus scriptum erat: Haec dicit Dominus Deus David patris tui: Quoniam non ambulasti in via Iosaphat patris tui, et in viis Asa regis Iuda,',
        13: 'sed incessisti per iter regum Israel, et fornicari fecisti Iudam, et habitatores Ierusalem, imitatus fornicationem domus Achab, insuper et fratres tuos domum patris tui, meliores te occidisti:',
        14: 'ecce Dominus percutiet te plaga magna cum populo tuo, et filiis, et uxoribus tuis, universaque substantia tua.',
        15: 'tu autem aegrotabis pessimo languore uteri tui, donec egrediantur vitalia tua paulatim per singulos dies.',
        16: 'Suscitavit ergo Dominus contra Ioram spiritum Philisthinorum, et Arabum, qui confines sunt Aethiopibus.',
        17: 'et ascenderunt in Terram Iuda, et vastaverunt eam, diripueruntque cunctam substantiam, quae inventa est in domo regis, insuper et filios eius, et uxores: nec remansit ei filius, nisi Ioachaz, qui minimus natu erat.',
        18: 'Et super haec omnia percussit eum Dominus alvi languore insanabili.',
        19: 'Cumque diei succederet dies, et temporum spatia volverentur, duorum annorum expletus est circulus: et sic longa consumptus tabe, ita ut egereret etiam viscera sua, languore pariter, et vita caruit. Mortuusque est in infirmitate pessima, et non fecit ei populus secundum morem combustionis, exequias, sicut fecerat maioribus eius.',
        20: 'Trigintaduorum annorum fuit, cum regnare coepisset, et octo annis regnavit in Ierusalem. Ambulavitque non recte, et sepelierunt eum in Civitate David: verumtamen non in sepulchro regum.',
    },
    22: {
        1: 'Constituerunt autem habitatores Ierusalem Ochoziam filium eius minimum, regem pro eo: omnes enim maiores natu, qui ante eum fuerant, interfecerant latrones Arabum, qui irruerant in castra: regnavitque Ochozias filius Ioram regis Iuda.',
        2: 'Quadraginta duorum annorum erat Ochozias cum regnare coepisset, et uno anno regnavit in Ierusalem, et nomen matris eius Athalia filia Amri.',
        3: 'Sed et ipse ingressus est per vias domus Achab: mater enim eius impulit eum ut impie ageret.',
        4: 'Fecit igitur malum in conspectu Domini, sicut domus Achab: ipsi enim fuerunt ei consiliarii post mortem patris sui, in interitum eius.',
        5: 'Ambulavitque in consiliis eorum. Et perrexit cum Ioram filio Achab rege Israel, in bellum contra Hazael regem Syriae in Ramoth Galaad: vulneraveruntque Syri Ioram.',
        6: 'Qui reversus est ut curaretur in Iezrahel: multas enim plagas acceperat in supradicto certamine. Igitur Ochozias filius Ioram rex Iuda, descendit ut inviseret Ioram filium Achab in Iezrahel aegrotantem.',
        7: 'Voluntatis quippe fuit Dei adversus Ochoziam, ut veniret ad Ioram: et cum venisset, et egrederetur cum eo adversum Iehu filium Namsi, quem unxit Dominus ut deleret domum Achab.',
        8: 'Cum ergo everteret Iehu domum Achab, invenit principes Iuda, et filios fratrum Ochoziae, qui ministrabant ei, et interfecit illos.',
        9: 'Ipsum quoque perquirens Ochoziam, comprehendit latitantem in Samaria: adductumque ad se, occidit, et sepelierunt eum: eo quod esset filius Iosaphat, qui quaesierat Dominum in toto corde suo. nec erat ultra spes aliqua ut de stirpe quis regnaret Ochoziae.',
        10: 'siquidem Athalia mater eius videns quod mortuus esset filius suus, surrexit, et interfecit omnem stirpem regiam domus Ioram.',
        11: 'Porro Iosabeth filia regis tulit Ioas filium Ochoziae, et furata est eum de medio filiorum regis, cum interficerentur: absconditque eum cum nutrice sua in cubiculo lectulorum: Iosabeth autem, quae absconderat eum, erat filia regis Ioram, uxor Ioiadae pontificis, soror Ochoziae, et idcirco Athalia non interfecit eum.',
        12: 'Fuit ergo cum eis in domo Dei absconditus sex annis, quibus regnavit Athalia super terram.',
    },
    23: {
        1: 'Anno autem septimo confortatus Ioiada, assumpsit centuriones, Azariam videlicet filium Ieroham, et Ismahel filium Iohanan, Azariam quoque filium Obed, et Maasiam filium Adaiae, et Elisaphat filium Zechri: et iniit cum eis foedus.',
        2: 'Qui circumeuntes Iudam, congregaverunt Levitas de cunctis urbibus Iuda, et principes familiarum Israel, veneruntque in Ierusalem.',
        3: 'Iniit ergo omnis multitudo pactum in domo Dei cum rege: dixitque ad eos Ioiada: Ecce filius regis regnabit, sicut locutus est Dominus super filios David.',
        4: 'Iste est ergo sermo quem facietis:',
        5: 'Tertia pars vestrum qui veniunt ad Sabbatum, Sacerdotum, et Levitarum, et ianitorum erit in portis: tertia vero pars ad domum regis: et tertia ad portam, quae appellatur Fundamenti: omne vero reliquum vulgus sit in atriis domus Domini.',
        6: 'Nec quispiam alius ingrediatur domum Domini, nisi Sacerdotes, et qui ministrant de Levitis: ipsi tantummodo ingrediantur, quia sanctificati sunt: et omne reliquum vulgus observet custodias Domini.',
        7: 'Levitae autem circumdent regem, habentes singuli arma sua: (et si quis alius ingressus fuerit templum, interficiatur) sintque cum rege et intrante et egrediente.',
        8: 'Fecerunt ergo Levitae, et universus Iuda iuxta omnia, quae praeceperat Ioiada pontifex: et assumpserunt singuli viros qui sub se erant, et veniebant per ordinem sabbati, cum his qui impleverant sabbatum, et egressi erant. siquidem Ioiada pontifex non dimiserat abire turmas, quae sibi per singulas hebdomadas succedere consueverant.',
        9: 'Deditque Ioiada sacerdos centurionibus lanceas, clypeosque et peltas regis David, quas consecraverat in domo Domini.',
        10: 'Constituitque omnem populum tenentium pugiones a parte templi dextra, usque ad partem templi sinistram, coram altari, et templo, per circuitum regis.',
        11: 'Et eduxerunt filium regis, et imposuerunt ei diadema, et testimonium, dederuntque in manu eius tenendam legem, et constituerunt eum regem: unxit quoque illum Ioiada pontifex, et filii eius: imprecatique sunt ei, atque dixerunt: Vivat rex.',
        12: 'Quod cum audisset Athalia, vocem scilicet currentium atque laudantium regem, ingressa est ad populum in templum Domini.',
        13: 'Cumque vidisset regem stantem super gradum in introitu, et principes, turmasque circa eum, omnemque populum terrae gaudentem, atque clangentem tubis, et diversi generis organis concinentem, vocemque laudantium, scidit vestimenta sua, et ait: Insidiae, insidiae.',
        14: 'Egressus autem Ioiada pontifex ad centuriones, et principes exercitus, dixit eis: Educite illam extra septa templi, et interficiatur foris gladio. Praecepitque sacerdos ne occideretur in domo Domini.',
        15: 'Et imposuerunt cervicibus eius manus: cumque intrasset portam equorum domus regis, interfecerunt eam ibi.',
        16: 'Pepigit autem Ioiada foedus inter se, universumque populum, et regem, ut esset populus Domini.',
        17: 'Itaque ingressus est omnis populus domum Baal, et destruxerunt eam: et altaria ac simulacra illius confregerunt: Mathan quoque sacerdotem Baal interfecerunt ante aras.',
        18: 'Constituit autem Ioiada praepositos in domo Domini, sub manibus Sacerdotum, et Levitarum, quos distribuit David in domo Domini: ut offerrent holocausta Domino, sicut scriptum est in lege Moysi, in gaudio et canticis, iuxta dispositionem David.',
        19: 'Constituit quoque ianitores in portis domus Domini, ut non ingrederetur eam immundus in omni re.',
        20: 'Assumpsitque centuriones, et fortissimos viros ac principes populi, et omne vulgus terrae, et fecerunt descendere regem de domo Domini, et introire per medium portae superioris in domum regis, et collocaverunt eum in solio regali.',
        21: 'Laetatusque est omnis populus terrae, et urbs quievit: porro Athalia interfecta est gladio.',
    },
    24: {
        1: 'Septem annorum erat Ioas cum regnare coepisset: et quadraginta annis regnavit in Ierusalem, nomen matris eius Sebia de Bersabee.',
        2: 'Fecitque quod bonum est coram Domino cunctis diebus Ioiadae sacerdotis.',
        3: 'Accepit autem ei Ioiada uxores duas, e quibus genuit filios et filias.',
        4: 'Post quae placuit Ioas ut instauraret domum Domini.',
        5: 'Congregavitque Sacerdotes, et Levitas, et dixit eis: Egredimini ad civitates Iuda, et colligite de universo Israel pecuniam ad sartatecta templi Dei nostri, per singulos annos, festinatoque hoc facite: porro Levitae egere negligentius.',
        6: 'Vocavitque rex Ioiadam principem, et dixit ei: Quare tibi non fuit curae, ut cogeres Levitas inferre de Iuda et de Ierusalem pecuniam, quae constituta est a Moyse servo Domini, ut inferret eam omnis multitudo Israel in tabernaculum testimonii?',
        7: 'Athalia enim impiissima, et filii eius destruxerunt domum Dei, et de universis, quae sanctificata fuerant in templo Domini, ornaverunt fanum Baalim.',
        8: 'Praecepit ergo rex, et fecerunt arcam: posueruntque eam iuxta portam domus Domini forinsecus.',
        9: 'Et praedicatum est in Iuda et Ierusalem ut deferrent singuli pretium Domino, quod constituit Moyses servus Dei super omnem Israel in deserto.',
        10: 'Laetatique sunt cuncti principes, et omnis populus: et ingressi contulerunt in arcam Domini, atque miserunt ita ut impleretur.',
        11: 'Cumque tempus esset ut deferrent arcam coram rege per manus Levitarum (videbant enim multam pecuniam) ingrediebatur scriba regis, et quem primus sacerdos constituerat: effundebantque pecuniam quae erat in arca: porro arcam reportabant ad locum suum: sicque faciebant per singulos dies, et congregata est infinita pecunia.',
        12: 'Quam dederunt rex et Ioiada his, qui praeerant operibus domus Domini: at illi conducebant ex ea caesores lapidum, et artifices operum singulorum ut instaurarent domum Domini: fabros quoque ferri et aeris, ut quod cadere coeperat, fulciretur.',
        13: 'Egeruntque hi qui operabantur industrie, et obducebatur parietum cicatrix per manus eorum, ac suscitaverunt domum Domini in statum pristinum, et firmiter eam stare fecerunt.',
        14: 'Cumque complessent omnia opera, detulerunt coram rege, et Ioiada reliquam partem pecuniae: de qua facta sunt vasa templi in ministerium, et ad holocausta, phialae quoque, et cetera vasa aurea et argentea: offerebantur holocausta in domo Domini iugiter cunctis diebus Ioiadae.',
        15: 'Senuit autem Ioiada plenus dierum, et mortuus est cum esset centum triginta annorum.',
        16: 'sepelieruntque eum in civitate David cum regibus, eo quod fecisset bonum cum Israel, et cum domo eius.',
        17: 'Postquam autem obiit Ioiada, ingressi sunt principes Iuda, et adoraverunt regem, qui delinitus obsequiis eorum, acquievit eis.',
        18: 'Et dereliquerunt templum Domini Dei patrum suorum, servieruntque lucis et sculptilibus, et facta est ira contra Iuda, et Ierusalem propter hoc peccatum.',
        19: 'Mittebatque eis prophetas ut reverterentur ad Dominum, quos protestantes, illi audire nolebant.',
        20: 'Spiritus itaque Dei induit Zachariam filium Ioiadae sacerdotem, et stetit in conspectu populi, et dixit eis: Haec dicit Dominus Deus: Quare transgredimini praeceptum Domini, quod vobis non proderit, et dereliquistis Dominum ut derelinqueret vos?',
        21: 'Qui congregati adversus eum, miserunt lapides iuxta regis imperium in atrio domus Domini.',
        22: 'Et non est recordatus Ioas rex misericordiae, quam fecerat Ioiada pater illius secum, sed interfecit filium eius. Qui cum moreretur, ait: Videat Dominus, et requirat.',
        23: 'Cumque evolutus esset annus, ascendit contra eum exercitus Syriae: venitque in Iuda et Ierusalem, et interfecit cunctos principes populi, atque universam praedam miserunt regi in Damascum.',
        24: 'Et certe cum permodicus venisset numerus Syrorum, tradidit Dominus in manibus eorum infinitam multitudinem, eo quod dereliquissent Dominum Deum patrum suorum: in Ioas quoque ignominiosa exercuere iudicia.',
        25: 'Et abeuntes dimiserunt eum in languoribus magnis: surrexerunt autem contra eum servi sui in ultionem sanguinis filii Ioiadae sacerdotis, et occiderunt eum in lectulo suo, et mortuus est: sepelieruntque eum in Civitate David, sed non in sepulchris regum.',
        26: 'Insidiati vero sunt ei Zabad filius Semmaath Ammanitidis, et Iozabad filius Semarith Moabitidis.',
        27: 'Porro filii eius, ac summa pecuniae, quae adunata fuerat sub eo, et instauratio domus Dei scripta sunt diligentius in Libro regum: regnavit autem Amasias filius eius pro eo.',
    },
    25: {
        1: 'Vigintiquinque annorum erat Amasias cum regnare coepisset, et vigintinovem annis regnavit in Ierusalem, nomen matris eius Ioadau de Ierusalem.',
        2: 'Fecitque bonum in conspectu Domini: verumtamen non in corde perfecto.',
        3: 'Cumque roboratum sibi videret imperium, iugulavit servos, qui occiderant regem patrem suum,',
        4: 'sed filios eorum non interfecit sicut scriptum est in Libro legis Moysi, ubi praecepit Dominus, dicens: Non occidentur patres pro filiis, neque filii pro patribus suis, sed unusquisque in suo peccato morietur.',
        5: 'Congregavit igitur Amasias Iuda, et constituit eos per familias, tribunosque et centuriones in universo Iuda, et Beniamin: et recensuit a viginti annis sursum, invenitque triginta millia iuvenum, qui egrederentur ad pugnam, et tenerent hastam et clypeum:',
        6: 'Mercede quoque conduxit de Israel centum millia robustorum, centum talentis argenti.',
        7: 'Venit autem homo Dei ad illum, et ait: O rex, ne egrediatur tecum exercitus Israel: non est enim Dominus cum Israel, et cunctis filiis Ephraim:',
        8: 'quod si putas in robore exercitus bella consistere, superari te faciet Deus ab hostibus: Dei quippe est et adiuvare, et in fugam convertere.',
        9: 'Dixitque Amasias ad hominem Dei: Quid ergo fiet de centum talentis, quae dedi militibus Israel? Et respondit ei homo Dei: Habet Dominus unde tibi dare possit multo his plura.',
        10: 'Separavit itaque Amasias exercitum, qui venerat ad eum ex Ephraim, ut reverteretur in locum suum: at illi contra Iuda vehementer irati, reversi sunt in regionem suam.',
        11: 'Porro Amasias confidenter eduxit populum suum, et abiit in Vallem salinarum, percussitque filios Seir decem millia.',
        12: 'Et alia decem millia virorum ceperunt filii Iuda, et adduxerunt ad praeruptum cuiusdam petrae, praecipitaveruntque eos de summo in praeceps, qui universi crepuerunt.',
        13: 'At ille exercitus, quem remiserat Amasias ne secum iret ad praelium, diffusus est in civitatibus Iuda a Samaria usque ad Bethoron, et interfectis tribus millibus, diripuit praedam magnam.',
        14: 'Amasias vero post caedem Idumaeorum, et allatos deos filiorum Seir, statuit illos in deos sibi, et adorabat eos, et illis adolebat incensum.',
        15: 'Quam ob rem iratus Dominus contra Amasiam misit ad illum prophetam, qui diceret ei: Cur adorasti deos, qui non liberaverunt populum suum de manu tua?',
        16: 'Cumque haec ille loqueretur, respondit ei: Num consiliarius regis es? quiesce ne interficiam te. Discedensque propheta, Scio, inquit, quod cogitaverit Deus occidere te, quia fecisti hoc malum, et insuper non acquievisti consilio meo.',
        17: 'Igitur Amasias rex Iuda inito pessimo consilio, misit ad Ioas filium Ioahaz filii Iehu, regem Israel, dicens: Veni, videamus nos mutuo.',
        18: 'At ille remisit nuncios, dicens: Carduus, qui est in Libano, misit ad cedrum Libani, dicens: Da filiam tuam filio meo uxorem: et ecce bestiae, quae erant in silva Libani, transierunt, et conculcaverunt carduum.',
        19: 'Dixisti: Percussi Edom, et idcirco erigitur cor tuum in superbiam: sede in domo tua, cur malum adversum te provocas, ut cadas et tu, et Iuda tecum?',
        20: 'Noluit audire Amasias, eo quod Domini esset voluntas ut traderetur in manus hostium propter deos Edom.',
        21: 'Ascendit igitur Ioas rex Israel, et mutuos sibi praebuere conspectus: Amasias autem rex Iuda erat in Bethsames Iuda:',
        22: 'corruitque Iuda coram Israel, et fugit in tabernacula sua.',
        23: 'Porro Amasiam regem Iuda, filium Ioas filii Ioahaz, cepit Ioas rex Israel in Bethsames, et adduxit in Ierusalem: destruxitque murum eius a porta Ephraim usque ad portam anguli quadringentis cubitis.',
        24: 'Omne quoque aurum, et argentum, et universa vasa, quae repererat in domo Dei, et apud Obededom in thesauris etiam domus regiae, necnon et filios obsidum reduxit in Samariam.',
        25: 'Vixit autem Amasias filius Ioas rex Iuda, postquam mortuus est Ioas filius Ioahaz rex Israel, quindecim annis.',
        26: 'Reliqua autem sermonum Amasiae priorum et novissimorum scripta sunt in Libro regum Iuda et Israel.',
        27: 'Qui postquam recessit a Domino, tetenderunt ei insidias in Ierusalem. Cumque fugisset in Lachis, miserunt, et interfecerunt eum ibi.',
        28: 'Reportantesque super equos, sepelierunt eum cum patribus suis in Civitate David.',
    },
    26: {
        1: 'Omnis autem populus Iuda filium eius Oziam annorum sedecim, constituit regem pro Amasia patre suo.',
        2: 'Ipse aedificavit Ailath, et restituit eam ditioni Iuda, postquam dormivit rex cum patribus suis.',
        3: 'Sedecim annorum erat Ozias cum regnare coepisset, et quinquagintaduobus annis regnavit in Ierusalem, nomen matris eius Iechelia de Ierusalem.',
        4: 'Fecitque quod erat rectum in oculis Domini iuxta omnia, quae fecerat Amasias pater eius.',
        5: 'Et exquisivit Dominum in diebus Zachariae intelligentis et videntis Deum: cumque requireret Dominum, direxit eum in omnibus.',
        6: 'Denique egressus est, et pugnavit contra Philisthiim, et destruxit murum Geth, et murum Iabniae, murumque Azoti: aedificavit quoque oppida in Azoto, et in Philisthiim.',
        7: 'Et adiuvit eum Deus contra Philisthiim, et contra Arabes, qui habitabant in Gurbaal, et contra Ammonitas.',
        8: 'Appendebantque Ammonitae munera Oziae: et divulgatum est nomen eius usque ad introitum Aegypti propter crebras victorias.',
        9: 'Aedificavitque Ozias turres in Ierusalem super portam anguli, et super portam vallis, et reliquas in eodem muri latere, firmavitque eas.',
        10: 'Extruxit etiam turres in solitudine, et effodit cisternas plurimas, eo quod haberet multa pecora tam in campestribus, quam in eremi vastitate: vineas quoque habuit et vinitores in montibus, et in carmelo: erat quippe homo agriculturae deditus.',
        11: 'Fuit autem exercitus bellatorum eius, qui procedebant ad praelia sub manu Iehiel scribae, Maasiaeque doctoris, et sub manu Hananiae, qui erat de ducibus regis.',
        12: 'Omnisque numerus principum per familias virorum fortium, duorum millium sexcentorum.',
        13: 'Et sub eis universus exercitus trecentorum et septem millium quingentorum: qui erant apti ad bella, et pro rege contra adversarios dimicabant.',
        14: 'Praeparavit quoque eis Ozias, id est, cuncto exercitui, clypeos, et hastas, et galeas, et loricas, arcusque et fundas ad iaciendos lapides.',
        15: 'Et fecit in Ierusalem diversi generis machinas, quas in turribus collocavit, et in angulis murorum ut mitterent sagittas, et saxa grandia: egressumque est nomen eius procul, eo quod auxiliaretur ei Dominus, et corroborasset illum.',
        16: 'Sed cum roboratus esset, elevatum est cor eius in interitum suum, et neglexit Dominum Deum suum: ingressusque templum Domini, adolere voluit incensum super altare thymiamatis.',
        17: 'Statimque ingressus post eum Azarias sacerdos, et cum eo Sacerdotes Domini octoginta, viri fortissimi,',
        18: 'restiterunt regi, atque dixerunt: Non est tui officii Ozia ut adoleas incensum Domino, sed Sacerdotum, hoc est, filiorum Aaron, qui consecrati sunt ad huiuscemodi ministerium: egredere de sanctuario, ne contempseris: quia non reputabitur tibi in gloriam hoc a Domino Deo.',
        19: 'Iratusque Ozias, tenens in manu thuribulum ut adoleret incensum, minabatur Sacerdotibus. Statimque orta est lepra in fronte eius coram Sacerdotibus, in domo Domini super altare thymiamatis.',
        20: 'Cumque respexisset eum Azarias pontifex, et omnes reliqui Sacerdotes, viderunt lepram in fronte eius, et festinato expulerunt eum. Sed et ipse perterritus, acceleravit egredi, eo quod sensisset illico plagam Domini.',
        21: 'Fuit igitur Ozias rex leprosus usque ad diem mortis suae, et habitavit in domo separata plenus lepra, ob quam eiectus fuerat de domo Domini. Porro Ioatham filius eius rexit domum regis, et iudicabat populum terrae.',
        22: 'Reliqua autem sermonum Oziae priorum et novissimorum scripsit Isaias filius Amos, propheta.',
        23: 'Dormivitque Ozias cum patribus suis, et sepelierunt eum in agro regalium sepulchrorum, eo quod esset leprosus: regnavitque Ioatham filius eius pro eo.',
    },
    27: {
        1: 'Vigintiquinque annorum erat Ioatham cum regnare coepisset, et sedecim annis regnavit in Ierusalem: nomen matris eius Ierusa filia Sadoc.',
        2: 'Fecitque quod rectum erat coram Domino iuxta omnia quae fecerat Ozias pater suus, excepto quod non est ingressus templum Domini, et adhuc populus delinquebat.',
        3: 'Ipse aedificavit portam domus Domini excelsam, et in muro Ophel multa construxit.',
        4: 'Urbes quoque aedificavit in montibus Iuda, et in saltibus castella, et turres.',
        5: 'Ipse pugnavit contra regem filiorum Ammon, et vicit eos, dederuntque ei filii Ammon in tempore illo centum talenta argenti, et decem millia coros tritici, ac totidem coros hordei: haec ei praebuerunt filii Ammon in anno secundo et tertio.',
        6: 'Corroboratusque est Ioatham eo quod direxisset vias suas coram Domino Deo suo.',
        7: 'Reliqua autem sermonum Ioatham, et omnes pugnae eius, et opera, scripta sunt in Libro regum Israel et Iuda.',
        8: 'Vigintiquinque annorum erat cum regnare coepisset, et sedecim annis regnavit in Ierusalem.',
        9: 'Dormivitque Ioatham cum patribus suis, et sepelierunt eum in Civitate David: et regnavit Achaz filius eius pro eo.',
    },
    28: {
        1: 'Viginti annorum erat Achaz cum regnare coepisset: et sedecim annis regnavit in Ierusalem: non fecit rectum in conspectu Domini sicut David pater eius:',
        2: 'sed ambulavit in viis regum Israel, insuper et statuas fudit Baalim.',
        3: 'Ipse est, qui adolevit incensum in Valle benennom, et lustravit filios suos in igne iuxta ritum gentium, quas interfecit Dominus in adventu filiorum Israel.',
        4: 'Sacrificabat quoque, et thymiama succendebat in excelsis, et in collibus, et sub omni ligno frondoso.',
        5: 'Tradiditque eum Dominus Deus eius in manu regis Syriae, qui percussit eum, magnamque praedam cepit de eius imperio, et adduxit in Damascum: manibus quoque regis Israel traditus est, et percussus plaga grandi.',
        6: 'Occiditque Phacee, filius Romeliae, de Iuda centum viginti millia in die uno, omnes viros bellatores: eo quod reliquissent Dominum Deum patrum suorum.',
        7: 'Eodem tempore occidit Zechri, vir potens ex Ephraim, Maasiam filium regis, et Ezricam ducem domus eius, Elcanam quoque secundum a rege.',
        8: 'Ceperuntque filii Israel de fratribus suis ducenta millia mulierum, puerorum, et puellarum, et infinitam praedam: pertuleruntque eam in Samariam.',
        9: 'Ea tempestate erat ibi propheta Domini, nomine Obed: qui egressus obviam exercitui venienti in Samariam, dixit eis: Ecce iratus Dominus Deus patrum vestrorum contra Iuda, tradidit eos in manibus vestris, et occidistis eos atrociter, ita ut ad caelum pertingeret vestra crudelitas.',
        10: 'Insuper filios Iuda, et Ierusalem vultis vobis subiicere in servos et ancillas. quod nequaquam facto opus est: peccastis enim super hoc Domino Deo vestro.',
        11: 'Sed audite consilium meum, et reducite captivos, quos adduxistis de fratribus vestris, quia magnus furor Domini imminet vobis.',
        12: 'Steterunt itaque viri de principibus filiorum Ephraim, Azarias filius Iohanan, Barachias filius Mosollamoth, Ezechias filius Sellum, et Amasa filius Hadali, contra eos, qui veniebant de praelio,',
        13: 'et dixerunt eis: Non introducetis huc captivos, ne peccemus Domino. Quare vultis adiicere super peccata nostra, et vetera cumulare delicta? grande quippe peccatum est, et ira furoris Domini imminet super Israel.',
        14: 'Dimiseruntque viri bellatores praedam, et universa quae ceperant coram principibus, et omni multitudine.',
        15: 'Steteruntque viri, quos supra memoravimus, et apprehendentes captivos, omnesque qui nudi erant, vestierunt de spoliis: cumque vestissent eos, et calceassent, et refecissent cibo ac potu, unxissentque propter laborem, et adhibuissent eis curam: quicumque ambulare non poterant, et erant imbecillo corpore, imposuerunt eos iumentis, et adduxerunt Iericho Civitatem palmarum ad fratres eorum, ipsique reversi sunt in Samariam.',
        16: 'Tempore illo misit rex Achaz ad regem Assyriorum, postulans auxilium.',
        17: 'Veneruntque Idumaei, et percusserunt multos ex Iuda, et ceperunt praedam magnam.',
        18: 'Philisthiim quoque diffusi sunt per urbes campestres, et ad Meridiem Iuda: ceperuntque Bethsames, et Aialon, et Gaderoth, Socho quoque, et Thamnan, et Gamzo, cum viculis suis, et habitaverunt in eis.',
        19: 'Humiliaverat enim Dominus Iudam propter Achaz regem Iuda, eo quod nudasset eum auxilio, et contemptui habuisset Dominum.',
        20: 'Adduxitque contra eum Thelgathphalnasar regem Assyriorum, qui et afflixit eum, et nullo resistente vastavit.',
        21: 'Igitur Achaz spoliata domo Domini, et domo regum, ac principum, dedit regi Assyriorum munera, et tamen nihil ei profuit.',
        22: 'Insuper et tempore angustiae suae auxit contemptum in Dominum, ipse per se rex Achaz,',
        23: 'immolavit diis Damasci victimas percussoribus suis, et dixit: Dii regum Syriae auxiliantur eis, quos ego placabo hostiis, et aderunt mihi, cum econtrario ipsi fuerint ruinae ei, et universo Israel.',
        24: 'Direptis itaque Achaz omnibus vasis domus Dei, atque confractis, clausit ianuas templi Dei, et fecit sibi altaria in universis angulis Ierusalem.',
        25: 'In omnibus quoque urbibus Iuda extruxit aras ad cremandum thus, atque ad iracundiam provocavit Dominum Deum patrum suorum.',
        26: 'Reliqua autem sermonum eius, et omnium operum suorum priorum et novissimorum scripta sunt in Libro regum Iuda et Israel.',
        27: 'Dormivitque Achaz cum patribus suis, et sepelierunt eum in civitate Ierusalem: neque enim receperunt eum in sepulchra regum Israel. Regnavitque Ezechias filius eius pro eo.',
    },
    29: {
        1: 'Igitur Ezechias regnare coepit, cum vigintiquinque esset annorum, et vigintinovem annis regnavit in Ierusalem: nomen matris eius Abia, filia Zachariae.',
        2: 'Fecitque quod erat placitum in conspectu Domini iuxta omnia quae fecerat David pater eius.',
        3: 'Ipse anno, et mense primo regni sui aperuit valvas domus Domini, et instauravit eas.',
        4: 'adduxitque Sacerdotes atque Levitas, et congregavit eos in plateam Orientalem.',
        5: 'Dixitque ad eos: Audite me Levitae, et sanctificamini, mundate domum Domini Dei patrum vestrorum, et auferte omnem immunditiam de sanctuario.',
        6: 'Peccaverunt patres nostri, et fecerunt malum in conspectu Domini Dei nostri, derelinquentes eum: averterunt facies suas a tabernaculo Domini, et praebuerunt dorsum.',
        7: 'Clauserunt ostia, quae erant in porticu, et extinxerunt lucernas, incensumque non adoleverunt, et holocausta non obtulerunt in sanctuario Deo Israel.',
        8: 'Concitatus est itaque furor Domini super Iudam et Ierusalem, tradiditque eos in commotionem, et in interitum, et in sibilum, sicut ipsi cernitis oculis vestris.',
        9: 'En, corruerunt patres nostri gladiis, filii nostri, et filiae nostrae, et coniuges captivae ductae sunt propter hoc scelus.',
        10: 'Nunc ergo placet mihi ut ineamus foedus cum Domino Deo Israel, et avertet a nobis furorem irae suae.',
        11: 'Filii mei nolite negligere: vos elegit Dominus ut stetis coram eo, et ministretis illi, colatisque eum, et cremetis ei incensum.',
        12: 'Surrexerunt ergo Levitae: Mahath filius Amasai, et Ioel filius Azariae de filiis Caath: Porro de filiis Merari, Cis filius Abdi, et Azarias filius Ialaleel. De filiis autem Gersom, Ioah filius Zemma, et Eden filius Ioah.',
        13: 'At vero de filiis Elisaphan, Samri, et Iahiel. De filiis quoque Asaph, Zacharias, et Mathanias:',
        14: 'Necnon de filiis Heman, Iahiel, et Semei: Sed et de filiis Idithun, Semeias, et Oziel.',
        15: 'Congregaveruntque fratres suos, et sanctificati sunt, et ingressi sunt iuxta mandatum regis et imperium Domini, ut expiarent domum Dei.',
        16: 'Sacerdotes quoque ingressi templum Domini ut sanctificarent illud, extulerunt omnem immunditiam, quam intro repererant in vestibulo domus Domini, quam tulerunt Levitae, et asportaverunt ad Torrentem cedron foras.',
        17: 'Coeperunt autem prima die mensis primi mundare, et in die octavo eiusdem mensis ingressi sunt porticum templi Domini, expiaveruntque templum diebus octo, et in die sextadecima mensis eiusdem, quod coeperant impleverunt.',
        18: 'Ingressi quoque sunt ad Ezechiam regem, et dixerunt ei: Sanctificavimus omnem domum Domini, et altare holocausti, vasaque eius, necnon et mensam propositionis cum omnibus vasis suis,',
        19: 'cunctamque templi supellectilem, quam polluerat rex Achaz in regno suo, postquam praevaricatus est: et ecce exposita sunt omnia coram altare Domini.',
        20: 'Consurgensque diluculo Ezechias rex, adunavit omnes principes civitatis, et ascendit in domum Domini:',
        21: 'obtuleruntque simul tauros septem, et arietes septem, agnos septem, et hircos septem pro peccato, pro regno, pro sanctuario, pro Iuda, dixitque sacerdotibus filiis Aaron ut offerrent super altare Domini.',
        22: 'Mactaverunt igitur tauros, et susceperunt sanguinem Sacerdotes, et fuderunt illum super altare, mactaverunt etiam arietes, et illorum sanguinem super altare fuderunt, immolaveruntque agnos, et fuderunt super altare sanguinem.',
        23: 'Applicuerunt hircos pro peccato coram rege, et universa multitudine, imposueruntque manus suas super eos:',
        24: 'et immolaverunt illos Sacerdotes, et asperserunt sanguinem eorum coram altare pro piaculo universi Israelis: pro omni quippe Israel praeceperat rex ut holocaustum fieret et pro peccato.',
        25: 'Constituit quoque Levitas in domo Domini cum cymbalis, et psalteriis, et citharis secundum dispositionem David regis, et Gad Videntis, et Nathan prophetae: siquidem Domini praeceptum fuit per manum prophetarum eius.',
        26: 'Steteruntque Levitae tenentes organa David, et Sacerdotes tubas.',
        27: 'Et iussit Ezechias ut offerrent holocausta super altare: cumque offerrentur holocausta, coeperunt laudes canere Domino, et clangere tubis, atque in diversis organis, quae David rex Israel praeparaverat, concrepare.',
        28: 'Omni autem turba adorante, cantores, et ii, qui tenebant tubas, erant in officio suo donec compleretur holocaustum.',
        29: 'Cumque finita esset oblatio, incurvatus est rex, et omnes qui erant cum eo, et adoraverunt.',
        30: 'Praecepitque Ezechias, et principes Levitis ut laudarent Dominum sermonibus David, et Asaph Videntis: qui laudaverunt eum magna laetitia, et incurvato genu adoraverunt.',
        31: 'Ezechias autem etiam haec addidit: Implestis manus vestras Domino, accedite, et offerte victimas, et laudes in domo Domini. Obtulit ergo universa multitudo hostias, et laudes, et holocausta mente devota.',
        32: 'Porro numerus holocaustorum, quae obtulit multitudo, hic fuit, Tauros septuaginta, arietes centum, agnos ducentos.',
        33: 'Sanctificaveruntque Domino boves sexcentos, et oves tria millia.',
        34: 'Sacerdotes vero pauci erant, nec poterant sufficere ut pelles holocaustorum detraherent: unde et Levitae fratres eorum adiuverunt eos, donec impleretur opus, et sanctificarentur antistites: Levitae quippe faciliori ritu sanctificantur, quam Sacerdotes.',
        35: 'Fuerunt ergo holocausta plurima, adipes pacificorum, et libamina holocaustorum: et completus est cultus domus Domini.',
        36: 'Laetatusque est Ezechias, et omnis populus eo quod ministerium Domini esset expletum. De repente quippe hoc fieri placuerat.',
    },
    30: {
        1: 'Misit quoque Ezechias ad omnem Israel et Iudam: scripsitque epistolas ad Ephraim et Manassen ut venirent ad domum Domini in Ierusalem, et facerent Phase Domino Deo Israel.',
        2: 'Inito ergo consilio regis et principum, et universi coetus Ierusalem, decreverunt ut facerent Phase mense secundo.',
        3: 'Non enim occurerant facere in tempore suo, quia sacerdotes, qui possent sufficere, sanctificati non fuerant, et populus nondum congregatus fuerat in Ierusalem.',
        4: 'Placuitque sermo regi, et omni multitudini.',
        5: 'Et decreverunt ut mitterent nuncios in universum Israel de Bersabee usque Dan ut venirent, et facerent Phase Domino Deo Israel in Ierusalem: multi enim non fecerant sicut lege praescriptum est.',
        6: 'Perrexeruntque cursores cum epistolis ex regis imperio, et principum eius, in universum Israel et Iudam iuxta id, quod rex iusserat, praedicantes: Filii Israel revertimini ad Dominum Deum Abraham, et Isaac, et Israel: et revertetur ad reliquias, quae effugerunt manum regis Assyriorum.',
        7: 'Nolite fieri sicut patres vestri, et fratres qui recesserunt a Domino Deo patrum suorum, qui tradidit eos in interitum, ut ipsi cernitis.',
        8: 'Nolite indurare cervices vestras, sicut patres vestri: tradite manus Domino, et venite ad sanctuarium eius, quod sanctificavit in aeternum: servite Domino Deo patrum vestrorum, et avertetur a vobis ira furoris eius.',
        9: 'Si enim vos reversi fueritis ad Dominum: fratres vestri, et filii habebunt misericordiam coram dominis suis, qui illos duxerunt captivos, et revertentur in terram hanc: pius enim et clemens est Dominus Deus vester, et non avertet faciem suam a vobis, si reversi fueritis ad eum.',
        10: 'Igitur cursores pergebant velociter de civitate in civitatem per terram Ephraim, et Manasse usque ad Zabulon, illis irridentibus et subsannantibus eos.',
        11: 'Attamen quidam viri ex Aser, et Manasse, et Zabulon acquiescentes consilio, venerunt Ierusalem.',
        12: 'In Iuda vero facta est manus Domini ut daret eis cor unum, ut facerent iuxta praeceptum regis, et principum verbum Domini.',
        13: 'Congregatique sunt in Ierusalem populi multi ut facerent sollemnitatem azymorum, in mense secundo:',
        14: 'et surgentes destruxerunt altaria quae erant in Ierusalem, atque universa, in quibus idolis adolebatur incensum, subvertentes, proiecerunt in Torrentem cedron.',
        15: 'Immolaverunt autem Phase quartadecima die mensis secundi. Sacerdotes quoque, atque Levitae tandem sanctificati obtulerunt holocausta in domo Domini:',
        16: 'Steteruntque in ordine suo iuxta dispositionem, et legem Moysi hominis Dei: Sacerdotes vero suscipiebant effundendum sanguinem de manibus Levitarum,',
        17: 'eo quod multa turba sanctificata non esset: et idcirco immolarent Levitae Phase his, qui non occurrerant sanctificari Domino.',
        18: 'Magna etiam pars populi de Ephraim, et Manasse, et Issachar, et Zabulon, quae sanctificata non fuerat, comedit Phase, non iuxta quod scriptum est: et oravit pro eis Ezechias, dicens: Dominus bonus propitiabitur',
        19: 'cunctis, qui in toto corde requirunt Dominum Deum patrum suorum: et non imputabit eis quod minus sanctificati sunt.',
        20: 'Quem exaudivit Dominus, et placatus est populo.',
        21: 'Feceruntque filii Israel, qui inventi sunt in Ierusalem, sollemnitatem azymorum septem diebus in laetitia magna, laudantes Dominum per singulos dies: Levitae quoque, et Sacerdotes per organa, quae suo officio congruebant.',
        22: 'Et locutus est Ezechias ad cor omnium Levitarum, qui habebant intelligentiam bonam super Domino: et comederunt septem diebus sollemnitatis, immolantes victimas pacificorum, et laudantes Dominum Deum patrum suorum.',
        23: 'Placuitque universae multitudini ut celebrarent etiam alios dies septem: quod et fecerunt cum ingenti gaudio.',
        24: 'Ezechias enim rex Iuda praebuerat multitudini mille tauros, et septem millia ovium: principes vero dederant populo tauros mille, et oves decem millia: sanctificata est ergo sacerdotum plurima multitudo.',
        25: 'Et hilaritate perfusa omnis turba Iuda tam Sacerdotum et Levitarum, quam universae frequentiae, quae venerat ex Israel; proselytorum quoque de Terra Israel, et habitantium in Iuda.',
        26: 'Factaque est grandis celebritas in Ierusalem, qualis a diebus Salomonis filii David regis Israel in ea urbe non fuerat.',
        27: 'Surrexerunt autem Sacerdotes atque Levitae benedicentes populo: et exaudita est vox eorum: pervenitque oratio in habitaculum sanctum caeli.',
    },
    31: {
        1: 'Cumque haec fuissent rite celebrata, egressus est omnis Israel, qui inventus fuerat in urbibus Iuda, et fregerunt simulacra, succideruntque lucos, demoliti sunt excelsa, et altaria destruxerunt, non solum de universo Iuda et Beniamin, sed et de Ephraim quoque et Manasse, donec penitus everterent: reversique sunt omnes filii Israel in possessiones et civitates suas.',
        2: 'Ezechias autem constituit turmas Sacerdotales, et Leviticas per divisiones suas, unumquemque in officio proprio, tam Sacerdotum videlicet quam Levitarum ad holocausta, et pacifica ut ministrarent et confiterentur, canerentque in portis castrorum Domini.',
        3: 'Pars autem regis erat, ut de propria eius substantia offerretur holocaustum, mane semper et vespere. Sabbatis quoque, et Calendis, et sollemnitatibus ceteris, sicut scriptum est in lege Moysi.',
        4: 'Praecepit etiam populo habitantium Ierusalem ut darent partes Sacerdotibus, et Levitis, ut possent vacare legi Domini.',
        5: 'Quod cum percrebruisset in auribus multitudinis, plurimas obtulere primitias filii Israel frumenti, vini, et olei, mellis quoque: et omnium, quae gignit humus, decimas obtulerunt.',
        6: 'Sed et filii Israel et Iuda, qui habitabant in urbibus Iuda, obtulerunt decimas boum et ovium, decimasque sanctorum, quae voverant Domino Deo suo: atque universa portantes, fecerunt acervos plurimos.',
        7: 'Mense tertio coeperunt acervorum iacere fundamenta, et mense septimo compleverunt eos.',
        8: 'Cumque ingressi fuissent Ezechias, et principes eius, viderunt acervos, et benedixerunt Domino ac populo Israel.',
        9: 'Interrogavitque Ezechias Sacerdotes, et Levitas cur ita iacerent acervi.',
        10: 'Respondit illi Azarias Sacerdos primus de stirpe Sadoc, dicens: Ex quo coeperunt offerri primitiae in domo Domini, comedimus, et saturati sumus, et remanserunt plurima, eo quod benedixerit Dominus populo suo: reliquarum autem copia est ista, quam cernis.',
        11: 'Praecepit igitur Ezechias ut praepararent horrea in domo Domini. Quod cum fecissent,',
        12: 'intulerunt tam primitias, quam decimas, et quaecumque voverant, fideliter. Fuit autem praefectus eorum Chonenias Levita, et Semei frater eius, secundus,',
        13: 'post quem Iahiel, et Azarias, et Nahath, et Asael, et Ierimoth, Iozabad quoque, et Eliel, et Iesmachias, et Mahath, et Banaias, praepositi sub manibus Choneniae, et Semei fratris eius, ex imperio Ezechiae regis et Azariae pontificis domus Dei, ad quos omnia pertinebant.',
        14: 'Core vero filius Iemna Levites et ianitor Orientalis portae, praepositus erat iis, quae sponte offerebantur Domino, primitiisque et consecratis in Sancta sanctorum.',
        15: 'Et sub cura eius Eden, et Beniamin, Iesue, et Semeias, Amarias quoque, et Sechenias in civitatibus Sacerdotum ut fideliter distribuerent fratribus suis partes, minoribus atque maioribus:',
        16: 'exceptis maribus ab annis tribus et supra, cunctis qui ingrediebantur templum Domini, et quidquid per singulos dies conducebat in ministerio, atque observationibus iuxta divisiones suas,',
        17: 'Sacerdotibus per familias, et Levitis a vigesimo anno et supra, per ordines et turmas suas,',
        18: 'universaeque multitudini tam uxoribus, quam liberis eorum utriusque sexus, fideliter cibi de his, quae sanctificata fuerant, praebebantur.',
        19: 'Sed et filiorum Aaron per agros, et suburbana urbium singularum dispositi erant viri, qui partes distribuerent universo sexui masculino de Sacerdotibus, et Levitis.',
        20: 'Fecit ergo Ezechias universa quae diximus in omni Iuda: operatusque est bonum et rectum, et verum coram Domino Deo suo',
        21: 'in universa cultura ministerii domus Domini, iuxta legem et ceremonias, volens requirere Deum suum in toto corde suo: fecitque et prosperatus est.',
    },
    32: {
        1: 'Post quae et huiuscemodi veritatem, venit Sennacherib rex Assyriorum, et ingressus Iuda, obsedit civitates munitas, volens eas capere.',
        2: 'Quod cum vidisset Ezechias, venisse scilicet Sennacherib, et totum belli impetum verti contra Ierusalem,',
        3: 'inito cum principibus consilio, virisque fortissimis ut obturarent capita fontium, qui erant extra urbem: et hoc omnium decernente sententia,',
        4: 'congregavit plurimam multitudinem, et obturaverunt cunctos fontes, et rivum, qui fluebat in medio terrae, dicentes: Ne veniant reges Assyriorum, et inveniant aquarum abundantiam.',
        5: 'Aedificavit quoque, agens industrie, omnem murum, qui fuerat dissipatus, et extruxit turres desuper, et forinsecus alterum murum: instauravitque Mello in Civitate David, et fecit universi generis armaturam et clypeos:',
        6: 'constituitque principes bellatorum in exercitu: et convocavit universos in platea portae civitatis, ac locutus est ad cor eorum dicens:',
        7: 'Viriliter agite, et confortamini: nolite timere, nec paveatis regem Assyriorum, et universam multitudinem, quae est cum eo: multo enim plures nobiscum sunt, quam cum illo.',
        8: 'Cum illo enim est brachium carneum: nobiscum Dominus Deus noster, qui auxiliator est noster, pugnatque pro nobis. Confortatusque est populus huiuscemodi verbis Ezechiae regis Iuda.',
        9: 'Quae postquam gesta sunt, misit Sennacherib rex Assyriorum servos suos in Ierusalem (ipse enim cum universo exercitu obsidebat Lachis) ad Ezechiam regem Iuda, et ad omnem populum, qui erat in urbe, dicens:',
        10: 'Haec dicit Sennacherib rex Assyriorum: In quo habentes fiduciam sedetis obsessi in Ierusalem?',
        11: 'Num Ezechias decipit vos, ut tradat morti in fame et siti, affirmans quod Dominus Deus vester liberet vos de manu regis Assyriorum?',
        12: 'Numquid non iste est Ezechias, qui destruxit excelsa illius, et altaria, et praecepit Iuda et Ierusalem, dicens: Coram altare uno adorabitis, et in ipso comburetis incensum?',
        13: 'An ignoratis quae ego fecerim, et patres mei cunctis terrarum populis? numquid praevaluerunt dii gentium, omniumque terrarum liberare regionem suam de manu mea?',
        14: 'Quis est de universis diis gentium, quas vastaverunt patres mei, qui potuerit eruere populum suum de manu mea, ut possit etiam Deus vester eruere vos de hac manu?',
        15: 'Non vos ergo decipiat Ezechias, nec vana persuasione deludat, neque credatis ei. Si enim nullus potuit deus cunctarum gentium atque regnorum liberare populum suum de manu mea, et de manu patrum meorum, consequenter nec Deus vester poterit eruere vos de manu mea.',
        16: 'Sed et alia multa locuti sunt servi eius contra Dominum Deum, et contra Ezechiam servum eius.',
        17: 'epistolas quoque scripsit plenas blasphemiae in Dominum Deum Israel, et locutus est adversus eum: Sicut dii gentium ceterarum non potuerunt liberare populum suum de manu mea, sic et Deus Ezechiae eruere non poterit populum suum de manu ista.',
        18: 'Insuper et clamore magno, lingua Iudaica contra populum, qui sedebat in muris Ierusalem, personabat, ut terreret eos, et caperet civitatem.',
        19: 'Locutusque est contra Deum Ierusalem, sicut adversum deos populorum terrae, opera manuum hominum.',
        20: 'Oraverunt igitur Ezechias rex, et Isaias filius Amos prophetes, adversum hanc blasphemiam, ac vociferati sunt usque in caelum.',
        21: 'Et misit Dominus angelum, qui percussit omnem virum robustum, et bellatorem, et principem exercitus regis Assyriorum: Reversusque est cum ignominia in terram suam. Cumque ingressus esset domum Dei sui, filii qui egressi fuerant de utero eius, interfecerunt eum gladio.',
        22: 'Salvavitque Dominus Ezechiam et habitatores Ierusalem de manu Sennacherib regis Assyriorum, et de manu omnium, et praestitit eis quietem per circuitum.',
        23: 'Multi etiam deferebant hostias, et sacrificia Domino in Ierusalem, et munera Ezechiae regi Iuda: qui exaltatus est post haec coram cunctis gentibus.',
        24: 'In diebus illis aegrotavit Ezechias usque ad mortem, et oravit Dominum: exaudivitque eum, et dedit ei signum.',
        25: 'Sed non iuxta beneficia, quae acceperat, retribuit, quia elevatum est cor eius: et facta est contra eum ira, et contra Iuda et Ierusalem.',
        26: 'Humiliatusque est postea eo quod exaltatum fuisset cor eius, tam ipse, quam habitatores Ierusalem: et idcirco non venit super eos ira Domini in diebus Ezechiae.',
        27: 'Fuit autem Ezechias dives, et inclytus valde, et thesauros sibi plurimos congregavit argenti et auri et lapidis pretiosi, aromatum, et armorum universi generis, et vasorum magni pretii.',
        28: 'Apothecas quoque frumenti, vini, et olei, et praesepia omnium iumentorum, caulasque pecorum,',
        29: 'et urbes sex aedificavit sibi: habebat quippe greges ovium, et armentorum innumerabiles, eo quod dedisset ei Dominus substantiam multam nimis.',
        30: 'Ipse est Ezechias, qui obturavit superiorem fontem aquarum Gihon, et avertit eas subter ad Occidentem Urbis David: in omnibus operibus suis fecit prospere quae voluit.',
        31: 'Attamen in legatione principum Babylonis, qui missi fuerant ad eum, ut interrogarent de portento, quod acciderat super terram, dereliquit eum Deus ut tentaretur, et nota fierent omnia, quae erant in corde eius.',
        32: 'Reliqua autem sermonum Ezechiae, et misericordiarum eius scripta sunt in visione Isaiae filii Amos prophetae, et in libro regum Iuda et Israel.',
        33: 'Dormivitque Ezechias cum patribus suis, et sepelierunt eum super sepulchra filiorum David: et celebravit eius exequias universus Iuda, et omnes habitatores Ierusalem: regnavitque Manasses filius eius pro eo.',
    },
    33: {
        1: 'Duodecim annorum erat Manasses cum regnare coepisset, et quinquagintaquinque annis regnavit in Ierusalem.',
        2: 'Fecit autem malum coram Domino iuxta abominationes gentium, quas subvertit Dominus coram filiis Israel:',
        3: 'et conversus instauravit excelsa, quae demolitus fuerat Ezechias pater eius: construxitque aras Baalim, et fecit lucos, et adoravit omnem militiam caeli, et coluit eam.',
        4: 'Aedificavit quoque altaria in domo Domini, de qua dixerat Dominus: In Ierusalem erit nomen meum in aeternum.',
        5: 'Aedificavit autem ea cuncto exercitui caeli in duobus atriis domus Domini.',
        6: 'Transireque fecit filios suos per ignem in Vallebenennom: observabat somnia, sectabatur auguria, maleficis artibus inserviebat, habebat secum magos, et incantatores: multaque mala operatus est coram Domino ut irritaret eum.',
        7: 'Sculptile quoque, et conflatile signum posuit in domo Domini, de qua locutus est Dominus ad David, et ad Salomonem filium eius, dicens: In domo hac et in Ierusalem, quam elegi de cunctis tribubus Israel, ponam nomen meum in sempiternum.',
        8: 'Et moveri non faciam pedem Israel de terra, quam tradidi patribus eorum: ita dumtaxat si custodierint facere quae praecepi eis, cunctamque legem, et ceremonias, atque iudicia per manum Moysi.',
        9: 'Igitur Manasses seduxit Iuda, et habitatores Ierusalem ut facerent malum super omnes gentes, quas subverterat Dominus a facie filiorum Israel.',
        10: 'Locutusque est Dominus ad eum, et ad populum illius, et attendere noluerunt.',
        11: 'Idcirco superinduxit eis principes exercitus regis Assyriorum: ceperuntque Manassen, et vinctum catenis, atque compedibus duxerunt in Babylonem.',
        12: 'Qui postquam coangustatus est, oravit Dominum Deum suum: et egit poenitentiam valde coram Deo patrum suorum.',
        13: 'Deprecatusque est eum, et obsecravit intente: et exaudivit orationem eius, reduxitque eum Ierusalem in regnum suum, et cognovit Manasses quod Dominus ipse esset Deus.',
        14: 'Post haec aedificavit murum extra civitatem David ad Occidentem Gihon in convalle, ab introitu portae piscium per circuitum usque ad Ophel, et exaltavit illum vehementer: constituitque principes exercitus in cunctis civitatibus Iuda munitis:',
        15: 'et abstulit deos alienos, et simulacrum de domo Domini: aras quoque, quas fecerat in monte domus Domini, et in Ierusalem, et proiecit omnia extra urbem.',
        16: 'Porro instauravit altare Domini, et immolavit super illud victimas, et pacifica, et laudem: praecepitque Iuda ut serviret Domino Deo Israel.',
        17: 'Attamen adhuc populus immolabat in excelsis Domino Deo suo.',
        18: 'Reliqua autem gestorum Manasse: et obsecratio eius ad Deum suum: verba quoque Videntium, qui loquebantur ad eum in nomine Domini Dei Israel, continentur in sermonibus regum Israel.',
        19: 'Oratio quoque eius et exauditio, et cuncta peccata, atque contemptus, loca etiam, in quibus aedificavit excelsa, et fecit lucos, et statuas antequam ageret poenitentiam, scripta sunt in sermonibus Hozai.',
        20: 'Dormivit ergo Manasses cum patribus suis, et sepelierunt eum in domo sua: regnavitque pro eo filius eius Amon.',
        21: 'Vigintiduorum annorum erat Amon cum regnare coepisset, et duobus annis regnavit in Ierusalem.',
        22: 'Fecitque malum in conspectu Domini, sicut fecerat Manasses pater eius: et cunctis idolis, quae Manasses fuerat fabricatus, immolavit atque servivit.',
        23: 'Et non est reveritus faciem Domini, sicut reveritus est Manasses pater eius: et multo maiora deliquit.',
        24: 'Cumque coniurassent adversus eum servi sui, interfecerunt eum in domo sua.',
        25: 'Porro reliqua populi multitudo, caesis iis, qui Amon percusserant, constituit regem Iosiam filium eius pro eo.',
    },
    34: {
        1: 'Octo annorum erat Iosias cum regnare coepisset, et triginta et uno anno regnavit in Ierusalem.',
        2: 'Fecitque quod erat rectum in conspectu Domini, et ambulavit in viis David patris sui: non declinavit neque ad dextram, neque ad sinistram.',
        3: 'Octavo autem anno regni sui, cum adhuc esset puer, coepit quaerere Deum patris sui David: et duodecimo anno postquam coeperat, mundavit Iuda et Ierusalem ab excelsis, et lucis, simulacrisque et sculptilibus.',
        4: 'Destruxeruntque coram eo aras Baalim: et simulacra, quae superposita fuerant, demoliti sunt: lucos etiam, et sculptilia succidit atque comminuit: et super tumulos eorum, qui eis immolare consueverant, fragmenta dispersit.',
        5: 'Ossa praeterea sacerdotum combussit in altaribus idolorum, mundavitque Iuda et Ierusalem.',
        6: 'Sed et in urbibus Manasse, et Ephraim, et Simeon, usque Nephthali cuncta subvertit.',
        7: 'Cumque altaria dissipasset, et lucos, et sculptilia contrivisset in frustra, cunctaque delubra demolitus esset de universa Terra Israel, reversus est in Ierusalem.',
        8: 'Igitur anno octavodecimo regni sui, mundata iam terra, et templo Domini, misit Saphan filium Eseliae, et Maasiam principem civitatis, et Ioha filium Ioachaz a commentariis, ut instaurarent domum Domini Dei sui.',
        9: 'Qui venerunt ad Helciam Sacerdotem magnum: acceptamque ab eo pecuniam, quae illata fuerat in domum Domini, et quam congregaverant Levitae, et ianitores de Manasse, et Ephraim, et universis reliquiis Israel, ab omni quoque Iuda, et Beniamin, et habitatoribus Ierusalem,',
        10: 'tradiderunt in manibus eorum, qui praeerant operariis in domo Domini ut instaurarent templum, et infirma quaeque sarcirent.',
        11: 'At illi dederunt eam artificibus, et caementariis ut emerent lapides de lapicidinis, et ligna ad commissuras aedificii, et ad contignationem domorum, quas destruxerant reges Iuda.',
        12: 'Qui fideliter cuncta faciebant. Erant autem praepositi operantium, Iahath et Abdias de filiis Merari, Zacharias et Mosollam de filiis Caath, qui urgebant opus: omnes Levitae scientes organis canere.',
        13: 'Super eos vero, qui ad diversos usus onera portabant, erant scribae, et magistri de Levitis ianitores.',
        14: 'Cumque efferrent pecuniam, quae illata fuerat in templum Domini, reperit Helcias Sacerdos Librum legis Domini per manum Moysi.',
        15: 'Et ait ad Saphan scribam: Librum legis inveni in domo Domini: et tradidit ei.',
        16: 'At ille intulit volumen ad regem, et nunciavit ei dicens: Omnia, quae dedisti in manu servorum tuorum, ecce complentur.',
        17: 'Argentum, quod repertum est in domo Domini, conflaverunt: datumque est praefectis artificum, et diversa opera fabricantium.',
        18: 'Praeterea tradidit mihi Helcias sacerdos hunc librum. Quem cum rege praesente recitasset,',
        19: 'audissetque ille verba legis, scidit vestimenta sua:',
        20: 'et praecepit Helciae, et Ahicam filio Saphan, et Abdon filio Micha, Saphan quoque scribae, et Asaae servo regis, dicens:',
        21: 'Ite, et orate Dominum pro me, et pro reliquiis Israel, et Iuda, super universis sermonibus Libri istius, qui repertus est: magnus enim furor Domini stillavit super nos, eo quod non custodierint patres nostri verba Domini ut facerent omnia, quae scripta sunt in isto volumine.',
        22: 'Abiit ergo Helcias, et hi qui simul a rege missi fuerant, ad Oldam prophetidem, uxorem Sellum filii Thecuath, filii Hasra custodis vestium: quae habitabat in Ierusalem in Secunda: et locuti sunt ei verba, quae supra narravimus.',
        23: 'At illa respondit eis: Haec dicit Dominus Deus Israel: Dicite viro, qui misit vos ad me:',
        24: 'Haec dicit Dominus: Ecce ego inducam mala super locum istum, et super habitatores eius, cunctaque maledicta, quae scripta sunt in Libro hoc, quem legerunt coram rege Iuda.',
        25: 'Quia dereliquerunt me, et sacrificaverunt diis alienis, ut me ad iracundiam provocarent in cunctis operibus manuum suarum, idcirco stillabit furor meus super locum istum, et non extinguetur.',
        26: 'Ad regem autem Iuda, qui misit vos pro Domino deprecando, sic loquimini: Haec dicit Dominus Deus Israel: Quoniam audisti verba voluminis,',
        27: 'atque emollitum est cor tuum, et humiliatus es in conspectu Domini super his, quae dicta sunt contra locum hunc, et habitatores Ierusalem, reveritusque faciem meam, scidisti vestimenta tua, et flevisti coram me: ego quoque exaudivi te, dicit Dominus.',
        28: 'Iam enim colligam te ad patres tuos, et infereris in sepulchrum tuum in pace: nec videbunt oculi tui omne malum, quod ego inducturus sum super locum istum, et super habitatores eius. Retulerunt itaque regi cuncta quae dixerat.',
        29: 'At ille convocatis universis maioribus natu Iuda et Ierusalem,',
        30: 'ascendit in domum Domini, unaque omnes viri Iuda et habitatores Ierusalem, Sacerdotes et Levitae, et cunctus populus a minimo usque ad maximum. Quibus audientibus in domo Domini, legit rex omnia verba voluminis:',
        31: 'et stans in tribunali suo, percussit foedus coram Domino ut ambularet post eum, et custodiret praecepta, et testimonia, et iustificationes eius in toto corde suo, et in tota anima sua, faceretque quae scripta sunt in volumine illo, quod legerat.',
        32: 'Adiuravit quoque super hoc omnes, qui reperti fuerant in Ierusalem, et Beniamin: et fecerunt habitatores Ierusalem iuxta pactum Domini Dei patrum suorum.',
        33: 'Abstulit ergo Iosias cunctas abominationes de universis regionibus filiorum Israel: et fecit omnes, qui residui erant in Israel, servire Domino Deo suo. Cunctis diebus eius non recesserunt a Domino Deo patrum suorum.',
    },
    35: {
        1: 'Fecit autem Iosias in Ierusalem Phase Domino, quod immolatum est quartadecima die mensis primi:',
        2: 'et constituit Sacerdotes in officiis suis, hortatusque est eos ut ministrarent in domo Domini.',
        3: 'Levitis quoque, ad quorum eruditionem omnis Israel sanctificabatur Domino, locutus est: Ponite arcam in sanctuario templi, quod aedificavit Salomon filius David rex Israel, nequaquam enim eam ultra portabitis: nunc autem ministrate Domino Deo vestro, et populo eius Israel.',
        4: 'Et praeparate vos per domos, et cognationes vestras in divisionibus singulorum, sicut praecepit David rex Israel, et descripsit Salomon filius eius.',
        5: 'Et ministrate in sanctuario per familias turmasque Leviticas,',
        6: 'et sanctificati immolate Phase: fratres etiam vestros, ut possint iuxta verba, quae locutus est Dominus in manu Moysi facere, praeparate.',
        7: 'Dedit praeterea Iosias omni populo, qui ibi fuerat inventus in sollemnitate Phase, agnos et hoedos de gregibus, et reliqui pecoris triginta millia, boum quoque tria millia. haec de regis universa substantia.',
        8: 'Duces quoque eius, sponte quod voverant, obtulerunt, tam populo, quam Sacerdotibus et Levitis. Porro Helcias, et Zacharias, et Iahiel principes domus Domini, dederunt sacerdotibus ad faciendum Phase pecora commixtim duo millia sexcenta, et boves trecentos.',
        9: 'Chonenias autem, et Semeias, etiam Nathanael et fratres eius, necnon Hasabias, et Iehiel, et Iosabad principes Levitarum, dederunt ceteris Levitis ad celebrandum Phase quinque millia pecorum, et boves quingentos.',
        10: 'Praeparatumque est ministerium, et steterunt Sacerdotes in officio suo: Levitae quoque in turmis, iuxta regis imperium.',
        11: 'Et immolatum est Phase: asperseruntque Sacerdotes manu sua sanguinem, et Levitae detraxerunt pelles holocaustorum:',
        12: 'et separaverunt ea ut darent per domos et familias singulorum, et offerrentur Domino, sicut scriptum est in Libro Moysi: de bobus quoque fecerunt similiter.',
        13: 'Et assaverunt Phase super ignem, iuxta quod in lege scriptum est: pacificas vero hostias coxerunt in lebetibus, et cacabis, et ollis, et festinato distribuerunt universae plebi:',
        14: 'sibi autem, et Sacerdotibus postea paraverunt: nam in oblatione holocaustorum et adipum usque ad noctem Sacerdotes fuerunt occupati: unde Levitae sibi, et Sacerdotibus filiis Aaron paraverunt novissimis.',
        15: 'Porro cantores filii Asaph stabant in ordine suo, iuxta praeceptum David, et Asaph, et Heman, et Idithun prophetarum regis: Ianitores vero per portas singulas observabant, ita ut nec puncto quidem discederent a ministerio: quam ob rem et fratres eorum Levitae paraverunt eis cibos.',
        16: 'Omnis igitur cultura Domini rite completa est in die illa ut facerent Phase, et offerrent holocausta super altare Domini, iuxta praeceptum regis Iosiae.',
        17: 'Feceruntque filii Israel, qui reperti fuerant ibi, Phase in tempore illo, et sollemnitatem azymorum septem diebus.',
        18: 'Non fuit Phase simile huic in Israel a diebus Samuelis prophetae: sed nec quisquam de cunctis regibus Israel fecit Phase sicut Iosias, Sacerdotibus, et Levitis, et omni Iuda, et Israel qui repertus fuerat, et habitantibus in Ierusalem.',
        19: 'Octavodecimo anno regni Iosiae hoc Phase celebratum est.',
        20: 'Postquam instauraverat Iosias templum, ascendit Nechao rex Aegypti ad pugnandum in Charcamis iuxta Euphraten: et processit in occursum eius Iosias.',
        21: 'At ille, missis ad eum nunciis, ait: Quid mihi et tibi est rex Iuda? non adversum te hodie venio, sed contra aliam pugno domum, ad quam me Deus festinato ire praecepit: desine adversum Deum facere, qui mecum est, ne interficiat te.',
        22: 'Noluit Iosias reverti, sed praeparavit contra eum bellum, nec acquievit sermonibus Nechao ex ore Dei: verum perrexit ut dimicaret in campo Mageddo.',
        23: 'Ibique vulneratus a sagittariis, dixit pueris suis: Educite me de praelio, quia oppido vulneratus sum.',
        24: 'Qui transtulerunt eum de curru in alterum currum, qui sequebatur eum more regio, et asportaverunt eum in Ierusalem, mortuusque est, et sepultus in mausoleo patrum suorum: et universus Iuda et Ierusalem luxerunt eum.',
        25: 'Ieremias maxime: cuius omnes cantores atque cantatrices, usque in praesentem diem lamentationes super Iosiam replicant, et quasi lex obtinuit in Israel: Ecce scriptum fertur in lamentationibus.',
        26: 'Reliqua autem sermonum Iosiae et misericordiarum eius: quae lege praecepta sunt Domini:',
        27: 'opera quoque illius prima et novissima, scripta sunt in Libro regum Iuda et Israel.',
    },
    36: {
        1: 'Tulit ergo populus terrae Ioachaz filium Iosiae, et constituit regem pro patre suo in Ierusalem.',
        2: 'Vigintitrium annorum erat Ioachaz, cum regnare coepisset, et tribus mensibus regnavit in Ierusalem.',
        3: 'Amovit autem eum rex Aegypti cum venisset in Ierusalem, et condemnavit terram centum talentis argenti, et talento auri.',
        4: 'Constituitque pro eo regem, Eliakim fratrem eius, super Iuda et Ierusalem: et vertit nomen eius Ioakim: ipsum vero Ioachaz tulit secum, et abduxit in Aegyptum.',
        5: 'Vigintiquinque annorum erat Ioakim cum regnare coepisset, et undecim annis regnavit in Ierusalem: fecitque malum coram Domino Deo suo.',
        6: 'Contra hunc ascendit Nabuchodonosor rex Chaldaeorum, et vinctum catenis duxit in Babylonem.',
        7: 'Ad quam et vasa Domini transtulit, et posuit ea in templo suo.',
        8: 'Reliqua autem verborum Ioakim, et abominationum eius, quas operatus est, et quae inventa sunt in eo, continentur in Libro regum Iuda et Israel. Regnavit autem Ioachin filius eius pro eo.',
        9: 'Octo annorum erat Ioachin cum regnare coepisset, et tribus mensibus, ac decem diebus regnavit in Ierusalem, fecitque malum in conspectu Domini.',
        10: 'Cumque anni circulus volveretur, misit Nabuchodonosor rex, qui adduxerunt eum in Babylonem, asportatis simul pretiosissimis vasis domus Domini: Regem vero constituit Sedechiam patruum eius super Iuda et Ierusalem.',
        11: 'Viginti et unius anni erat Sedechias cum regnare coepisset, et undecim annis regnavit in Ierusalem.',
        12: 'Fecitque malum in oculis Domini Dei sui, nec erubuit faciem Ieremiae prophetae, loquentis ad se ex ore Domini.',
        13: 'A rege quoque Nabuchodonosor recessit, qui adiuraverat eum per Deum: et induravit cervicem suam et cor ut non reverteretur ad Dominum Deum Israel.',
        14: 'Sed et universi principes sacerdotum, et populus, praevaricati sunt inique iuxta universas abominationes Gentium, et polluerunt domum Domini, quam sanctificaverat sibi in Ierusalem.',
        15: 'Mittebat autem Dominus Deus patrum suorum ad illos per manum nunciorum suorum de nocte consurgens, et quotidie commonens: eo quod parceret populo et habitaculo suo.',
        16: 'At illi subsannabant nuncios Dei, et parvipendebant sermones eius, illudebantque prophetis, donec ascenderet furor Domini in populum eius, et esset nulla curatio.',
        17: 'Adduxit enim super eos regem Chaldaeorum, et interfecit iuvenes eorum gladio in domo sanctuarii sui, non est misertus adolescentis, et virginis, et senis, nec decrepiti quidem, sed omnes tradidit in manibus eius.',
        18: 'Universaque vasa domus Domini tam maiora, quam minora, et thesauros templi, et regis, et principum transtulit in Babylonem.',
        19: 'Incenderunt hostes domum Dei, destruxeruntque murum Ierusalem, universas turres combusserunt, et quidquid pretiosum fuerat, demoliti sunt.',
        20: 'Siquis evaserat gladium, ductus in Babylonem servivit regi et filiis eius, donec imperaret rex Persarum,',
        21: 'ut compleretur sermo Domini ex ore Ieremiae, et celebraret terra sabbata sua: cunctis enim diebus desolationis egit sabbatum usque dum complerentur septuaginta anni.',
        22: 'Anno autem primo Cyri regis Persarum ad explendum sermonem Domini, quem locutus fuerat per os Ieremiae, suscitavit Dominus spiritum Cyri regis Persarum: qui iussit praedicari in universo regno suo, etiam per scripturam, dicens:',
        23: 'Haec dicit Cyrus rex Persarum: Omnia regna terrae dedit mihi Dominus Deus caeli, et ipse praecepit mihi ut aedificarem ei domum in Ierusalem, quae est in Iudaea: quis ex vobis est in omni populo eius? sit Dominus Deis suus cum eo, et ascendat.',
    },
}
